insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','easy','Light from the Sun takes about 8 minutes 20 seconds to reach the Earth. If light travels at 3,00,000 km a second, about how far is the Sun from the Earth?','सूर्य से प्रकाश को पृथ्वी तक पहुँचने में लगभग 8 मिनट 20 सेकंड लगते हैं। यदि प्रकाश 3,00,000 किमी प्रति सेकंड चलता है, तो सूर्य पृथ्वी से लगभग कितनी दूर है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 1}'::jsonb,'[{"id": "a", "body": "1.5 crore km", "body_hi": "1.5 करोड़ किमी", "isCorrect": false}, {"id": "b", "body": "15 crore km", "body_hi": "15 करोड़ किमी", "isCorrect": true}, {"id": "c", "body": "24.6 crore km", "body_hi": "24.6 करोड़ किमी", "isCorrect": false}, {"id": "d", "body": "150 crore km", "body_hi": "150 करोड़ किमी", "isCorrect": false}]'::jsonb,2.5,0.83,'8 minutes 20 seconds is 8 × 60 + 20 = 500 seconds. In 500 seconds light covers 500 × 3,00,000 = 15,00,00,000 km, that is 15 crore km (150 million km). 24.6 crore km reads 8 minutes 20 seconds as 820 seconds; 1.5 crore and 150 crore km each slip a zero.','8 मिनट 20 सेकंड = 8 × 60 + 20 = 500 सेकंड। 500 सेकंड में प्रकाश 500 × 3,00,000 = 15,00,00,000 किमी, यानी 15 करोड़ किमी (15 करोड़ = 150 मिलियन) चलता है। 24.6 करोड़ किमी, 8 मिनट 20 सेकंड को 820 सेकंड पढ़ता है; 1.5 करोड़ और 150 करोड़ किमी में एक-एक शून्य खिसक जाता है।','csat-l4-s09-qa-sdt-the-sun-s-distance-from-light-s-travel-time','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','Two numbers add up to 50. What is the largest value their product can take?','दो संख्याओं का योग 50 है। उनका गुणनफल अधिक से अधिक कितना हो सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 2}'::jsonb,'[{"id": "a", "body": "576", "body_hi": "576", "isCorrect": false}, {"id": "b", "body": "600", "body_hi": "600", "isCorrect": false}, {"id": "c", "body": "624", "body_hi": "624", "isCorrect": false}, {"id": "d", "body": "625", "body_hi": "625", "isCorrect": true}]'::jsonb,2.5,0.83,'For a fixed sum the product is largest when the two numbers are equal: 25 × 25 = 625. Moving them apart by any amount d gives (25 - d)(25 + d) = 625 - d², which is smaller. 624 = 24 × 26 assumes the numbers must be different; 600 = 20 × 30 is just one pair; 576 = 24² has no basis.','स्थिर योग के लिए गुणनफल तब सबसे बड़ा होता है जब दोनों संख्याएँ बराबर हों: 25 × 25 = 625। उन्हें किसी भी मात्रा d से अलग करने पर (25 - d)(25 + d) = 625 - d² मिलता है, जो छोटा है। 624 = 24 × 26 मान लेता है कि संख्याएँ अलग होनी चाहिए; 600 = 20 × 30 केवल एक जोड़ी है; 576 = 24² का कोई आधार नहीं।','csat-l4-s09-qa-nt-the-largest-product-for-a-fixed-sum','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','Each of two ropes takes exactly 60 minutes to burn from one end to the other, but each burns unevenly, so half a rope need not take 30 minutes. With the two ropes and a lighter, and no clock, which one of the following intervals can NOT be measured?','दो रस्सियों में से हर एक को एक सिरे से दूसरे तक जलने में ठीक 60 मिनट लगते हैं, पर हर एक असमान रूप से जलती है, इसलिए आधी रस्सी के लिए 30 मिनट लगना आवश्यक नहीं। दोनों रस्सियों और एक लाइटर से, बिना घड़ी के, निम्नलिखित में से कौन-सा अंतराल नहीं मापा जा सकता?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 3}'::jsonb,'[{"id": "a", "body": "15 minutes", "body_hi": "15 मिनट", "isCorrect": false}, {"id": "b", "body": "30 minutes", "body_hi": "30 मिनट", "isCorrect": false}, {"id": "c", "body": "45 minutes", "body_hi": "45 मिनट", "isCorrect": false}, {"id": "d", "body": "40 minutes", "body_hi": "40 मिनट", "isCorrect": true}]'::jsonb,2.5,0.83,'Lighting a rope at both ends burns it in 30 minutes, however unevenly it burns. Light rope 1 at both ends and rope 2 at one end: when rope 1 is gone, 30 minutes have passed and rope 2 has 30 minutes left; lighting rope 2''s other end then burns it out in 15 more minutes -- 45 minutes in all, with 15 and 30 marked along the way. Every time the ropes can mark is a multiple of 15 minutes, so 40 minutes cannot be measured. 15, 30 and 45 minutes are all marked by the method above.','रस्सी को दोनों सिरों से जलाने पर वह 30 मिनट में जल जाती है, चाहे जितनी असमान जले। रस्सी 1 को दोनों सिरों से और रस्सी 2 को एक सिरे से जलाएँ: रस्सी 1 ख़त्म होने पर 30 मिनट बीत चुके हैं और रस्सी 2 में 30 मिनट बचे हैं; तब रस्सी 2 का दूसरा सिरा जलाने से वह 15 मिनट और में जल जाती है -- कुल 45 मिनट, रास्ते में 15 और 30 चिह्नित होते हुए। रस्सियाँ जो भी समय चिह्नित कर सकती हैं वह 15 मिनट का गुणज होता है, इसलिए 40 मिनट नहीं मापे जा सकते। 15, 30 और 45 मिनट ऊपर के तरीक़े से चिह्नित होते हैं।','csat-l4-s09-qa-ph-two-ropes-that-burn-unevenly','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','A district plans to plant one lakh saplings this monsoon in order to increase its forest cover. Which one of the following would it be most important to know in judging whether the plan will achieve its aim?','एक ज़िला अपना वन-आवरण बढ़ाने के लिए इस मानसून में एक लाख पौधे लगाने की योजना बनाता है। योजना अपना उद्देश्य पूरा करेगी या नहीं, यह आँकने के लिए निम्नलिखित में से क्या जानना सबसे महत्त्वपूर्ण होगा?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 4}'::jsonb,'[{"id": "a", "body": "How many people from the district are expected to volunteer to plant the saplings", "body_hi": "ज़िले के कितने लोग पौधे लगाने के लिए स्वयंसेवा करेंगे, ऐसी अपेक्षा है", "isCorrect": false}, {"id": "b", "body": "Whether the planting will be done on a public holiday so that schools can take part", "body_hi": "क्या पौधे सार्वजनिक अवकाश पर लगाए जाएँगे ताकि विद्यालय भाग ले सकें", "isCorrect": false}, {"id": "c", "body": "How many saplings the neighbouring districts are planning to plant this monsoon", "body_hi": "पड़ोसी ज़िले इस मानसून में कितने पौधे लगाने की योजना बना रहे हैं", "isCorrect": false}, {"id": "d", "body": "What share of saplings from the district''s past drives survived to become trees", "body_hi": "ज़िले के पिछले अभियानों के पौधों का कितना भाग जीवित रहकर पेड़ बना", "isCorrect": true}]'::jsonb,2.5,0.83,'Forest cover grows only if saplings survive and grow into trees; planting a lakh achieves nothing if most of them die. The record of past drives is the best guide to how many will survive. The number of volunteers and the choice of day affect how the planting is done, not whether the trees survive; what neighbouring districts plant does not change this district''s cover.','वन-आवरण तभी बढ़ता है जब पौधे जीवित रहकर पेड़ बनें; यदि अधिकांश मर जाएँ तो एक लाख लगाने से कुछ नहीं होता। पिछले अभियानों का रिकॉर्ड यह जानने का सबसे अच्छा आधार है कि कितने बचेंगे। स्वयंसेवकों की संख्या और दिन का चुनाव रोपाई के ढंग को प्रभावित करते हैं, पेड़ों के बचने को नहीं; पड़ोसी ज़िले क्या लगाते हैं, इससे इस ज़िले का आवरण नहीं बदलता।','csat-l4-s09-lr-sc-what-to-ask-of-a-tree-planting-drive','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','hard','Two towns, P and Q, are 84 km apart. At 6 am Asha and Bina set out on foot from P towards Q, at 5 km/h and 7 km/h, and at the same moment Chetan sets out on a bicycle from Q towards P at 9 km/h. How long after meeting Bina does Chetan meet Asha?','दो कस्बे, P और Q, 84 किमी दूर हैं। सुबह 6 बजे आशा और बीना P से Q की ओर पैदल 5 किमी/घंटा और 7 किमी/घंटा की चाल से निकलती हैं, और उसी क्षण चेतन Q से P की ओर साइकिल पर 9 किमी/घंटा की चाल से निकलता है। बीना से मिलने के कितनी देर बाद चेतन आशा से मिलता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 5}'::jsonb,'[{"id": "a", "body": "30 min", "body_hi": "30 मिनट", "isCorrect": false}, {"id": "b", "body": "45 min", "body_hi": "45 मिनट", "isCorrect": true}, {"id": "c", "body": "1 h 10 min", "body_hi": "1 घंटा 10 मिनट", "isCorrect": false}, {"id": "d", "body": "2 h 6 min", "body_hi": "2 घंटे 6 मिनट", "isCorrect": false}]'::jsonb,2.5,0.83,'Chetan and Bina close the 84 km at 7 + 9 = 16 km/h, so they meet after 5 h 15 min; Chetan and Asha close it at 5 + 9 = 14 km/h, meeting after 6 hours. The gap is 45 minutes. (Or: when Chetan meets Bina, Asha is (7 - 5) × 5.25 = 10.5 km behind, and that gap closes at 5 + 9 = 14 km/h, in 45 minutes.) 1 h 10 min closes the 10.5 km at Chetan''s speed alone; 2 h 6 min at Asha''s alone; 30 min has no basis.','चेतन और बीना 84 किमी 7 + 9 = 16 किमी/घंटा से घटाते हैं, इसलिए 5 घंटे 15 मिनट बाद मिलते हैं; चेतन और आशा इसे 5 + 9 = 14 किमी/घंटा से घटाते हैं, 6 घंटे बाद मिलते हैं। अंतर 45 मिनट है। (या: जब चेतन बीना से मिलता है, आशा (7 - 5) × 5.25 = 10.5 किमी पीछे है, और यह दूरी 5 + 9 = 14 किमी/घंटा से 45 मिनट में घटती है।) 1 घंटा 10 मिनट 10.5 किमी को केवल चेतन की चाल से घटाता है; 2 घंटे 6 मिनट केवल आशा की चाल से; 30 मिनट का कोई आधार नहीं।','csat-l4-s09-qa-sdt-two-walkers-who-meet-one-cyclist','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In a study published in 1968, the psychologist Robert Rosenthal and the school principal Lenore Jacobson tested the pupils of an American primary school and then told the teachers that certain children -- in fact chosen at random -- were about to ''bloom'' intellectually. When the children were tested again some months later, those labelled bloomers had gained more than the others, especially in the youngest classes. The authors concluded that the teachers'' expectations had shaped how the children learned, perhaps through the warmth, attention and challenge the teachers gave them. The finding became famous as the Pygmalion effect. Later attempts to repeat the study found the effect real but usually small, and largest when teachers formed their expectations before they had come to know the children.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1968 में प्रकाशित एक अध्ययन में मनोवैज्ञानिक रॉबर्ट रोज़ेन्थल और विद्यालय की प्रधानाचार्य लेनोर जैकबसन ने एक अमेरिकी प्राथमिक विद्यालय के विद्यार्थियों की परीक्षा ली और फिर शिक्षकों को बताया कि कुछ बच्चे -- जो वास्तव में यादृच्छिक रूप से चुने गए थे -- बौद्धिक रूप से ''खिलने'' वाले हैं। कुछ महीने बाद जब बच्चों की फिर परीक्षा हुई, तो ''खिलने वाले'' कहे गए बच्चों ने बाक़ियों से अधिक प्रगति की थी, विशेषकर सबसे छोटी कक्षाओं में। लेखकों ने निष्कर्ष निकाला कि शिक्षकों की अपेक्षाओं ने बच्चों के सीखने को आकार दिया, शायद उस स्नेह, ध्यान और चुनौती के माध्यम से जो शिक्षकों ने उन्हें दी। यह निष्कर्ष पिग्मेलियन प्रभाव के नाम से प्रसिद्ध हुआ। अध्ययन को दोहराने के बाद के प्रयासों ने प्रभाव को वास्तविक पर प्रायः छोटा पाया, और सबसे बड़ा तब जब शिक्षकों ने बच्चों को जानने से पहले ही अपनी अपेक्षाएँ बना ली थीं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p01", "csat_order": 6}'::jsonb,'[{"id": "a", "body": "The children labelled as bloomers were in fact abler than the others from the very start.", "body_hi": "''खिलने वाले'' कहे गए बच्चे शुरू से ही वास्तव में बाक़ियों से अधिक योग्य थे।", "isCorrect": false}, {"id": "b", "body": "Intelligence tests are of no use, since their results depend entirely on what teachers think.", "body_hi": "बुद्धि परीक्षाएँ किसी काम की नहीं, क्योंकि उनके परिणाम पूरी तरह इस पर निर्भर हैं कि शिक्षक क्या सोचते हैं।", "isCorrect": false}, {"id": "c", "body": "What teachers expect of pupils can shape their progress, though usually only modestly.", "body_hi": "शिक्षकों की अपेक्षाएँ विद्यार्थियों की प्रगति को प्रभावित कर सकती हैं, यद्यपि प्रायः थोड़ा ही।", "isCorrect": true}, {"id": "d", "body": "Teachers'' expectations matter most once they have come to know their pupils very well.", "body_hi": "शिक्षकों की अपेक्षाएँ तब सबसे अधिक मायने रखती हैं जब वे अपने विद्यार्थियों को बहुत अच्छी तरह जान चुके हों।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage reports a famous finding that teachers'' expectations shaped pupils'' progress, and ends by noting that later studies found the effect real but usually small. It says the bloomers were chosen at random, so they were not truly abler; it does not say that intelligence tests are useless; and it finds the effect strongest when teachers did not yet know the children, not when they knew them well.','परिच्छेद एक प्रसिद्ध निष्कर्ष बताता है कि शिक्षकों की अपेक्षाओं ने विद्यार्थियों की प्रगति को आकार दिया, और यह कहकर समाप्त होता है कि बाद के अध्ययनों ने प्रभाव को वास्तविक पर प्रायः छोटा पाया। वह कहता है कि ''खिलने वाले'' यादृच्छिक रूप से चुने गए थे, इसलिए वे वास्तव में अधिक योग्य नहीं थे; वह यह नहीं कहता कि बुद्धि परीक्षाएँ बेकार हैं; और वह प्रभाव को तब सबसे बड़ा पाता है जब शिक्षक बच्चों को अभी जानते नहीं थे, तब नहीं जब अच्छी तरह जानते थे।','csat-l4-s09-rc-p01-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In a study published in 1968, the psychologist Robert Rosenthal and the school principal Lenore Jacobson tested the pupils of an American primary school and then told the teachers that certain children -- in fact chosen at random -- were about to ''bloom'' intellectually. When the children were tested again some months later, those labelled bloomers had gained more than the others, especially in the youngest classes. The authors concluded that the teachers'' expectations had shaped how the children learned, perhaps through the warmth, attention and challenge the teachers gave them. The finding became famous as the Pygmalion effect. Later attempts to repeat the study found the effect real but usually small, and largest when teachers formed their expectations before they had come to know the children.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1968 में प्रकाशित एक अध्ययन में मनोवैज्ञानिक रॉबर्ट रोज़ेन्थल और विद्यालय की प्रधानाचार्य लेनोर जैकबसन ने एक अमेरिकी प्राथमिक विद्यालय के विद्यार्थियों की परीक्षा ली और फिर शिक्षकों को बताया कि कुछ बच्चे -- जो वास्तव में यादृच्छिक रूप से चुने गए थे -- बौद्धिक रूप से ''खिलने'' वाले हैं। कुछ महीने बाद जब बच्चों की फिर परीक्षा हुई, तो ''खिलने वाले'' कहे गए बच्चों ने बाक़ियों से अधिक प्रगति की थी, विशेषकर सबसे छोटी कक्षाओं में। लेखकों ने निष्कर्ष निकाला कि शिक्षकों की अपेक्षाओं ने बच्चों के सीखने को आकार दिया, शायद उस स्नेह, ध्यान और चुनौती के माध्यम से जो शिक्षकों ने उन्हें दी। यह निष्कर्ष पिग्मेलियन प्रभाव के नाम से प्रसिद्ध हुआ। अध्ययन को दोहराने के बाद के प्रयासों ने प्रभाव को वास्तविक पर प्रायः छोटा पाया, और सबसे बड़ा तब जब शिक्षकों ने बच्चों को जानने से पहले ही अपनी अपेक्षाएँ बना ली थीं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The bloomers gained more because they were abler than their classmates to begin with.", "Later studies showed that teachers'' expectations make no difference to how pupils learn."], "statements_hi": ["''खिलने वालों'' ने अधिक प्रगति इसलिए की कि वे शुरू से ही अपने सहपाठियों से अधिक योग्य थे।", "बाद के अध्ययनों ने दिखाया कि शिक्षकों की अपेक्षाओं से विद्यार्थियों के सीखने पर कोई अंतर नहीं पड़ता।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p01", "csat_order": 7}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1: the bloomers were chosen at random, so their larger gains cannot be put down to greater ability at the start -- that is the whole point of choosing them at random. 2: the later studies found the effect real but small; that is not the same as finding that expectations make no difference.','कोई भी वैध नहीं। 1: ''खिलने वाले'' यादृच्छिक रूप से चुने गए थे, इसलिए उनकी अधिक प्रगति को शुरुआती अधिक योग्यता से नहीं जोड़ा जा सकता -- यादृच्छिक चुनाव का यही उद्देश्य है। 2: बाद के अध्ययनों ने प्रभाव को वास्तविक पर छोटा पाया; यह इस निष्कर्ष के समान नहीं कि अपेक्षाओं से कोई अंतर नहीं पड़ता।','csat-l4-s09-rc-p01-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the smallest positive integer n such that 2n is a perfect square and 3n is a perfect cube?','वह सबसे छोटा धनात्मक पूर्णांक n कौन-सा है जिसके लिए 2n पूर्ण वर्ग और 3n पूर्ण घन हो?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 8}'::jsonb,'[{"id": "a", "body": "72", "body_hi": "72", "isCorrect": true}, {"id": "b", "body": "108", "body_hi": "108", "isCorrect": false}, {"id": "c", "body": "144", "body_hi": "144", "isCorrect": false}, {"id": "d", "body": "216", "body_hi": "216", "isCorrect": false}]'::jsonb,2.5,0.83,'n can use only the primes 2 and 3: n = 2ᵃ × 3ᵇ. For 2n to be a square, a + 1 and b must be even; for 3n to be a cube, a and b + 1 must be multiples of 3. The smallest a that is odd and a multiple of 3 is 3; the smallest b that is even and one less than a multiple of 3 is 2. So n = 2³ × 3² = 72: 2n = 144 = 12² and 3n = 216 = 6³. 144 is 2n, not n; 108 gives 2n = 216, not a square; 216 gives 2n = 432, not a square either.','n में केवल अभाज्य 2 और 3 हो सकते हैं: n = 2ᵃ × 3ᵇ। 2n के वर्ग होने के लिए a + 1 और b सम होने चाहिए; 3n के घन होने के लिए a और b + 1, 3 के गुणज होने चाहिए। सबसे छोटा a जो विषम और 3 का गुणज हो, 3 है; सबसे छोटा b जो सम हो और 3 के गुणज से एक कम, 2 है। अतः n = 2³ × 3² = 72: 2n = 144 = 12² और 3n = 216 = 6³। 144, n नहीं बल्कि 2n है; 108 से 2n = 216 मिलता है, जो वर्ग नहीं; 216 से 2n = 432, वह भी वर्ग नहीं।','csat-l4-s09-qa-nt-twice-a-square-and-thrice-a-cube','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','''This bridge cannot be unsafe. If it were, the thousands of people who cross it every day would be in danger, and the city could not cope with closing it.'' Which one of the following best describes the flaw in this argument?','''यह पुल असुरक्षित नहीं हो सकता। यदि होता, तो रोज़ इसे पार करने वाले हज़ारों लोग ख़तरे में होते, और शहर इसे बंद करने का बोझ नहीं उठा सकता।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 9}'::jsonb,'[{"id": "a", "body": "It relies on the opinion of the people who cross the bridge instead of that of engineers.", "body_hi": "यह इंजीनियरों के बजाय पुल पार करने वाले लोगों की राय पर निर्भर करता है।", "isCorrect": false}, {"id": "b", "body": "It assumes that the city has already inspected the bridge and found it to be sound.", "body_hi": "यह मान लेता है कि शहर पुल का पहले ही निरीक्षण कर चुका है और उसे ठीक पाया है।", "isCorrect": false}, {"id": "c", "body": "It confuses the number of people who cross the bridge with the weight the bridge can bear.", "body_hi": "यह पुल पार करने वाले लोगों की संख्या को उस भार से भ्रमित करता है जो पुल सह सकता है।", "isCorrect": false}, {"id": "d", "body": "It concludes that a claim is false because its being true would have unwelcome results.", "body_hi": "यह किसी दावे को इसलिए झूठा मान लेता है कि उसके सच होने के परिणाम अप्रिय होंगे।", "isCorrect": true}]'::jsonb,2.5,0.83,'Whether the bridge is safe is a question of its condition. The argument instead points to how bad things would be if it were unsafe -- danger to commuters, a city unable to cope -- and treats that as a reason to believe it is safe. How unwelcome a fact would be is no evidence that it is false. The argument cites no one''s opinion, mentions no inspection, and does not discuss the bridge''s load at all.','पुल सुरक्षित है या नहीं, यह उसकी दशा का प्रश्न है। तर्क इसके बजाय यह बताता है कि यदि पुल असुरक्षित होता तो स्थिति कितनी बुरी होती -- यात्रियों को ख़तरा, शहर पर बोझ -- और उसे पुल के सुरक्षित होने का कारण मान लेता है। कोई तथ्य कितना अप्रिय होगा, यह उसके झूठे होने का प्रमाण नहीं। तर्क किसी की राय उद्धृत नहीं करता, किसी निरीक्षण का उल्लेख नहीं करता, और पुल के भार पर कुछ नहीं कहता।','csat-l4-s09-lr-sc-a-bridge-called-safe-because-the-alternative-is-alarming','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','medium','Machine A fills 20 bottles a minute and machine B fills 30 bottles a minute. A starts at 9:00 am and B at 9:05 am. At what time will the two machines have filled equal numbers of bottles?','मशीन A एक मिनट में 20 बोतलें भरती है और मशीन B एक मिनट में 30। A सुबह 9:00 बजे और B 9:05 बजे शुरू होती है। किस समय दोनों मशीनें बराबर बोतलें भर चुकी होंगी?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 10}'::jsonb,'[{"id": "a", "body": "9:07 am", "body_hi": "सुबह 9:07", "isCorrect": false}, {"id": "b", "body": "9:10 am", "body_hi": "सुबह 9:10", "isCorrect": false}, {"id": "c", "body": "9:15 am", "body_hi": "सुबह 9:15", "isCorrect": true}, {"id": "d", "body": "9:25 am", "body_hi": "सुबह 9:25", "isCorrect": false}]'::jsonb,2.5,0.83,'By 9:05 A has filled 100 bottles. B then gains 30 - 20 = 10 bottles a minute, so it catches up in 100 ÷ 10 = 10 minutes, at 9:15. Check: A has 15 × 20 = 300 and B 10 × 30 = 300. 9:07 divides A''s lead by both rates added (100 ÷ 50); 9:10 has B run only as long as A''s head start; 9:25 has no basis.','9:05 तक A 100 बोतलें भर चुकी है। फिर B हर मिनट 30 - 20 = 10 बोतलें आगे बढ़ती है, इसलिए वह 100 ÷ 10 = 10 मिनट में बराबर आ जाती है, 9:15 पर। जाँच: A ने 15 × 20 = 300 और B ने 10 × 30 = 300 भरीं। 9:07, A की बढ़त को दोनों दरों के योग से भाग देता है (100 ÷ 50); 9:10 में B केवल A की बढ़त के समय जितना चलती है; 9:25 का कोई आधार नहीं।','csat-l4-s09-qa-tw-two-filling-machines-started-apart','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','A square of side 3 cm is cut from each corner of a rectangular sheet measuring 20 cm × 12 cm, and the sides are then folded up to make an open box. What is the volume of the box?','20 सेमी × 12 सेमी माप की एक आयताकार शीट के हर कोने से 3 सेमी भुजा का एक वर्ग काटा जाता है, और फिर किनारों को मोड़कर एक खुला डिब्बा बनाया जाता है। डिब्बे का आयतन क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 11}'::jsonb,'[{"id": "a", "body": "252 cm³", "body_hi": "252 घन सेमी", "isCorrect": true}, {"id": "b", "body": "459 cm³", "body_hi": "459 घन सेमी", "isCorrect": false}, {"id": "c", "body": "504 cm³", "body_hi": "504 घन सेमी", "isCorrect": false}, {"id": "d", "body": "720 cm³", "body_hi": "720 घन सेमी", "isCorrect": false}]'::jsonb,2.5,0.83,'Cutting 3 cm from both ends of each side leaves a base of (20 - 6) × (12 - 6) = 14 cm × 6 cm, and the folded flaps make the box 3 cm deep. Volume = 14 × 6 × 3 = 252 cm³. 459 cm³ = 17 × 9 × 3 takes 3 cm off each length only once, forgetting that there are corners at both ends; 504 cm³ makes the box 6 cm deep, adding the two cuts together; 720 cm³ = 20 × 12 × 3 forgets that the corners were cut away.','हर भुजा के दोनों सिरों से 3 सेमी काटने पर (20 - 6) × (12 - 6) = 14 सेमी × 6 सेमी का आधार बचता है, और मोड़े गए किनारे डिब्बे को 3 सेमी गहरा बनाते हैं। आयतन = 14 × 6 × 3 = 252 घन सेमी। 459 घन सेमी = 17 × 9 × 3 हर लंबाई से 3 सेमी केवल एक बार घटाता है, यह भूलकर कि दोनों सिरों पर कोने हैं; 504 घन सेमी दोनों कटों को जोड़कर डिब्बे को 6 सेमी गहरा बना देता है; 720 घन सेमी = 20 × 12 × 3 भूल जाता है कि कोने काटे गए थे।','csat-l4-s09-qa-gm-an-open-box-folded-from-a-sheet','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In On Liberty, published in 1859, John Stuart Mill argued that the only purpose for which power can rightfully be used over a member of a civilised community, against their will, is to prevent harm to others. A person''s own good, physical or moral, was not in his view a sufficient reason: people may be argued with, persuaded or warned, but not compelled for their own sake. Mill defended this partly because individuals usually know their own interests best, and partly because a society that allows varied ''experiments of living'' learns which ways of life are worth following. The principle is easier to state than to apply. Almost any act affects others in some way, so much depends on what counts as harm. Mill himself excluded children from the principle, and many laws today -- requiring seat belts, for instance -- protect people from themselves, which strict followers of Mill would reject.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1859 में प्रकाशित ऑन लिबर्टी में जॉन स्टुअर्ट मिल ने तर्क दिया कि किसी सभ्य समाज के सदस्य पर, उसकी इच्छा के विरुद्ध, शक्ति के उचित प्रयोग का एकमात्र उद्देश्य दूसरों को हानि से बचाना है। उनके मत में व्यक्ति का अपना भला, शारीरिक या नैतिक, पर्याप्त कारण नहीं था: लोगों से बहस की जा सकती है, उन्हें समझाया या चेताया जा सकता है, पर उनके अपने भले के लिए उन पर दबाव नहीं डाला जा सकता। मिल ने इसका बचाव कुछ इसलिए किया कि व्यक्ति प्रायः अपने हित सबसे अच्छी तरह जानते हैं, और कुछ इसलिए कि जो समाज जीवन के विविध ''प्रयोगों'' की अनुमति देता है, वह सीखता है कि जीने के कौन-से ढंग अपनाने योग्य हैं। सिद्धांत को कहना लागू करने से आसान है। लगभग हर काम किसी न किसी तरह दूसरों को प्रभावित करता है, इसलिए बहुत कुछ इस पर निर्भर है कि हानि किसे माना जाए। मिल ने स्वयं बच्चों को इस सिद्धांत से बाहर रखा, और आज के बहुत-से क़ानून -- जैसे सीट बेल्ट अनिवार्य करने वाले -- लोगों को स्वयं उनसे बचाते हैं, जिन्हें मिल के कट्टर अनुयायी अस्वीकार करेंगे।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p02", "csat_order": 12}'::jsonb,'[{"id": "a", "body": "Liberty may be limited only to prevent harm to others, a rule easier to state than apply.", "body_hi": "स्वतंत्रता केवल दूसरों की हानि रोकने हेतु सीमित हो सकती है; यह नियम कहना आसान, लागू करना कठिन है।", "isCorrect": true}, {"id": "b", "body": "People should never be advised or warned about choices that affect only themselves.", "body_hi": "जो चुनाव केवल स्वयं को प्रभावित करते हैं, उनके बारे में लोगों को कभी सलाह या चेतावनी नहीं दी जानी चाहिए।", "isCorrect": false}, {"id": "c", "body": "Modern laws, such as those on seat belts, are all based on the harm principle that Mill set out.", "body_hi": "आज के क़ानून, जैसे सीट बेल्ट वाले, सभी मिल के बताए हानि-सिद्धांत पर आधारित हैं।", "isCorrect": false}, {"id": "d", "body": "Mill''s principle was meant above all to protect children from the harm they might do to themselves.", "body_hi": "मिल का सिद्धांत सबसे बढ़कर बच्चों को उस हानि से बचाने के लिए था जो वे स्वयं को पहुँचा सकते हैं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage states Mill''s principle -- compulsion only to prevent harm to others -- with his reasons for it, then shows the difficulty of applying it, since so much depends on what counts as harm. Mill allowed persuasion and warning, so he did not say people must never be advised; the passage does not claim that every modern law follows Mill -- it gives seat-belt laws as ones that do not; and Mill excluded children rather than putting them first.','परिच्छेद मिल का सिद्धांत -- दबाव केवल दूसरों को हानि से बचाने के लिए -- उसके कारणों सहित रखता है, फिर उसे लागू करने की कठिनाई दिखाता है, क्योंकि बहुत कुछ इस पर निर्भर है कि हानि किसे माना जाए। मिल ने समझाने और चेताने की अनुमति दी, इसलिए उन्होंने यह नहीं कहा कि लोगों को कभी सलाह न दी जाए; परिच्छेद यह दावा नहीं करता कि आज का हर क़ानून मिल के अनुसार है -- वह सीट बेल्ट क़ानूनों को ऐसे क़ानूनों के रूप में देता है जो नहीं हैं; और मिल ने बच्चों को सिद्धांत से बाहर रखा, सबसे आगे नहीं।','csat-l4-s09-rc-p02-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In On Liberty, published in 1859, John Stuart Mill argued that the only purpose for which power can rightfully be used over a member of a civilised community, against their will, is to prevent harm to others. A person''s own good, physical or moral, was not in his view a sufficient reason: people may be argued with, persuaded or warned, but not compelled for their own sake. Mill defended this partly because individuals usually know their own interests best, and partly because a society that allows varied ''experiments of living'' learns which ways of life are worth following. The principle is easier to state than to apply. Almost any act affects others in some way, so much depends on what counts as harm. Mill himself excluded children from the principle, and many laws today -- requiring seat belts, for instance -- protect people from themselves, which strict followers of Mill would reject.

Which one of the following laws would Mill''s principle most clearly allow?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1859 में प्रकाशित ऑन लिबर्टी में जॉन स्टुअर्ट मिल ने तर्क दिया कि किसी सभ्य समाज के सदस्य पर, उसकी इच्छा के विरुद्ध, शक्ति के उचित प्रयोग का एकमात्र उद्देश्य दूसरों को हानि से बचाना है। उनके मत में व्यक्ति का अपना भला, शारीरिक या नैतिक, पर्याप्त कारण नहीं था: लोगों से बहस की जा सकती है, उन्हें समझाया या चेताया जा सकता है, पर उनके अपने भले के लिए उन पर दबाव नहीं डाला जा सकता। मिल ने इसका बचाव कुछ इसलिए किया कि व्यक्ति प्रायः अपने हित सबसे अच्छी तरह जानते हैं, और कुछ इसलिए कि जो समाज जीवन के विविध ''प्रयोगों'' की अनुमति देता है, वह सीखता है कि जीने के कौन-से ढंग अपनाने योग्य हैं। सिद्धांत को कहना लागू करने से आसान है। लगभग हर काम किसी न किसी तरह दूसरों को प्रभावित करता है, इसलिए बहुत कुछ इस पर निर्भर है कि हानि किसे माना जाए। मिल ने स्वयं बच्चों को इस सिद्धांत से बाहर रखा, और आज के बहुत-से क़ानून -- जैसे सीट बेल्ट अनिवार्य करने वाले -- लोगों को स्वयं उनसे बचाते हैं, जिन्हें मिल के कट्टर अनुयायी अस्वीकार करेंगे।

मिल का सिद्धांत निम्नलिखित में से किस क़ानून की सबसे स्पष्ट अनुमति देगा?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p02", "csat_order": 13}'::jsonb,'[{"id": "a", "body": "A law forbidding adults to take part in dangerous sports such as mountaineering", "body_hi": "वयस्कों को पर्वतारोहण जैसे ख़तरनाक खेलों में भाग लेने से रोकने वाला क़ानून", "isCorrect": false}, {"id": "b", "body": "A law forbidding adults to eat food that is bad for their health", "body_hi": "वयस्कों को उनके स्वास्थ्य के लिए हानिकारक भोजन खाने से रोकने वाला क़ानून", "isCorrect": false}, {"id": "c", "body": "A law forbidding adults to spend their own savings on whatever they please", "body_hi": "वयस्कों को अपनी बचत मनचाही चीज़ों पर ख़र्च करने से रोकने वाला क़ानून", "isCorrect": false}, {"id": "d", "body": "A law punishing people who drive after drinking alcohol", "body_hi": "शराब पीकर गाड़ी चलाने वालों को दंड देने वाला क़ानून", "isCorrect": true}]'::jsonb,2.5,0.83,'Driving after drinking puts other road users at risk, so a law punishing it prevents harm to others -- the one ground Mill accepts. Banning adults from risky sports, from eating unhealthy food, or from spending their own savings as they please would compel people for their own good, which Mill rejects; at most they may be warned or persuaded.','शराब पीकर गाड़ी चलाना सड़क के दूसरे लोगों को जोखिम में डालता है, इसलिए उस पर दंड देने वाला क़ानून दूसरों को हानि से बचाता है -- वही एकमात्र आधार जिसे मिल स्वीकार करते हैं। वयस्कों पर जोखिम भरे खेलों, अस्वास्थ्यकर भोजन, या अपनी बचत मनचाहे ढंग से ख़र्च करने पर रोक लोगों पर उनके अपने भले के लिए दबाव डालती, जिसे मिल अस्वीकार करते हैं; अधिक से अधिक उन्हें चेताया या समझाया जा सकता है।','csat-l4-s09-rc-p02-a-law-mill-would-allow','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In On Liberty, published in 1859, John Stuart Mill argued that the only purpose for which power can rightfully be used over a member of a civilised community, against their will, is to prevent harm to others. A person''s own good, physical or moral, was not in his view a sufficient reason: people may be argued with, persuaded or warned, but not compelled for their own sake. Mill defended this partly because individuals usually know their own interests best, and partly because a society that allows varied ''experiments of living'' learns which ways of life are worth following. The principle is easier to state than to apply. Almost any act affects others in some way, so much depends on what counts as harm. Mill himself excluded children from the principle, and many laws today -- requiring seat belts, for instance -- protect people from themselves, which strict followers of Mill would reject.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1859 में प्रकाशित ऑन लिबर्टी में जॉन स्टुअर्ट मिल ने तर्क दिया कि किसी सभ्य समाज के सदस्य पर, उसकी इच्छा के विरुद्ध, शक्ति के उचित प्रयोग का एकमात्र उद्देश्य दूसरों को हानि से बचाना है। उनके मत में व्यक्ति का अपना भला, शारीरिक या नैतिक, पर्याप्त कारण नहीं था: लोगों से बहस की जा सकती है, उन्हें समझाया या चेताया जा सकता है, पर उनके अपने भले के लिए उन पर दबाव नहीं डाला जा सकता। मिल ने इसका बचाव कुछ इसलिए किया कि व्यक्ति प्रायः अपने हित सबसे अच्छी तरह जानते हैं, और कुछ इसलिए कि जो समाज जीवन के विविध ''प्रयोगों'' की अनुमति देता है, वह सीखता है कि जीने के कौन-से ढंग अपनाने योग्य हैं। सिद्धांत को कहना लागू करने से आसान है। लगभग हर काम किसी न किसी तरह दूसरों को प्रभावित करता है, इसलिए बहुत कुछ इस पर निर्भर है कि हानि किसे माना जाए। मिल ने स्वयं बच्चों को इस सिद्धांत से बाहर रखा, और आज के बहुत-से क़ानून -- जैसे सीट बेल्ट अनिवार्य करने वाले -- लोगों को स्वयं उनसे बचाते हैं, जिन्हें मिल के कट्टर अनुयायी अस्वीकार करेंगे।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["Mill would accept a law forbidding adults to eat unhealthy food, since their poor health may burden others.", "On Mill''s view, a person may be warned against a harmful habit even though they may not be forced to give it up."], "statements_hi": ["मिल वयस्कों को अस्वास्थ्यकर भोजन से रोकने वाला क़ानून स्वीकार करेंगे, क्योंकि उनका ख़राब स्वास्थ्य दूसरों पर बोझ बन सकता है।", "मिल के मत में किसी व्यक्ति को हानिकारक आदत के विरुद्ध चेताया जा सकता है, यद्यपि उसे वह आदत छोड़ने के लिए मजबूर नहीं किया जा सकता।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p02", "csat_order": 14}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 2 is valid. Mill says people may be argued with, persuaded or warned, though not compelled for their own sake, so warning someone against a harmful habit fits his view. 1 runs against the principle: a law forbidding adults to eat unhealthy food compels them for their own good, and Mill does not accept a person''s own good as a reason for compulsion.','केवल 2 वैध है। मिल कहते हैं कि लोगों से बहस की जा सकती है, उन्हें समझाया या चेताया जा सकता है, यद्यपि उनके अपने भले के लिए दबाव नहीं डाला जा सकता, इसलिए किसी को हानिकारक आदत के विरुद्ध चेताना उनके मत के अनुकूल है। 1 सिद्धांत के विरुद्ध जाता है: वयस्कों को अस्वास्थ्यकर भोजन से रोकने वाला क़ानून उन पर उनके अपने भले के लिए दबाव डालता है, और मिल व्यक्ति के अपने भले को दबाव का कारण नहीं मानते।','csat-l4-s09-rc-p02-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','medium','In a code, a word is split into two halves, and the letters of each half are written in reverse order. In this code SILVER is written as LISREV. How is MARKET written in the same code?','एक कूट में किसी शब्द को दो आधों में बाँटा जाता है, और हर आधे के अक्षर उलटे क्रम में लिखे जाते हैं। इस कूट में SILVER को LISREV लिखा जाता है। उसी कूट में MARKET कैसे लिखा जाएगा?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 15}'::jsonb,'[{"id": "a", "body": "TEKRAM", "body_hi": "TEKRAM", "isCorrect": false}, {"id": "b", "body": "RAMTEK", "body_hi": "RAMTEK", "isCorrect": true}, {"id": "c", "body": "KETMAR", "body_hi": "KETMAR", "isCorrect": false}, {"id": "d", "body": "MARTEK", "body_hi": "MARTEK", "isCorrect": false}]'::jsonb,2.5,0.83,'SILVER splits into SIL and VER; reversed, they give LIS and REV: LISREV, which confirms the rule. MARKET splits into MAR and KET, which reversed give RAM and TEK: RAMTEK. TEKRAM reverses the whole word; KETMAR swaps the halves without reversing them; MARTEK reverses only the second half.','SILVER, SIL और VER में बँटता है; उलटने पर LIS और REV मिलते हैं: LISREV, जिससे नियम की पुष्टि होती है। MARKET, MAR और KET में बँटता है, जो उलटने पर RAM और TEK देते हैं: RAMTEK। TEKRAM पूरे शब्द को उलट देता है; KETMAR आधों को उलटे बिना अदल-बदल देता है; MARTEK केवल दूसरे आधे को उलटता है।','csat-l4-s09-lr-cd-a-word-reversed-in-halves','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Time & Work','mcq','hard','Two taps together fill a tank in 12 hours. One tap alone takes 10 hours longer than the other alone. How long does the faster tap take to fill the tank on its own?','दो नल मिलकर एक टंकी 12 घंटे में भरते हैं। एक नल अकेले दूसरे से 10 घंटे अधिक लेता है। तेज़ नल अकेले टंकी भरने में कितना समय लेता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 16}'::jsonb,'[{"id": "a", "body": "15 h", "body_hi": "15 घंटे", "isCorrect": false}, {"id": "b", "body": "18 h", "body_hi": "18 घंटे", "isCorrect": false}, {"id": "c", "body": "20 h", "body_hi": "20 घंटे", "isCorrect": true}, {"id": "d", "body": "24 h", "body_hi": "24 घंटे", "isCorrect": false}]'::jsonb,2.5,0.83,'If the faster tap takes x hours, the slower takes x + 10, and 1/x + 1/(x + 10) = 1/12. Trying the options: 1/20 + 1/30 = 3/60 + 2/60 = 5/60 = 1/12, so x = 20 (the slower tap takes 30 hours). 24 h treats the taps as equal (each would then take twice the joint time), which the 10-hour gap rules out; 15 h and 18 h fail the check (1/15 + 1/25 and 1/18 + 1/28 are not 1/12).','यदि तेज़ नल x घंटे लेता है, तो धीमा x + 10 लेता है, और 1/x + 1/(x + 10) = 1/12। विकल्प आज़माएँ: 1/20 + 1/30 = 3/60 + 2/60 = 5/60 = 1/12, इसलिए x = 20 (धीमा नल 30 घंटे लेता है)। 24 घंटे नलों को बराबर मान लेता है (तब हर एक संयुक्त समय का दोगुना लेता), जिसे 10 घंटे का अंतर नकारता है; 15 और 18 घंटे जाँच में विफल हैं (1/15 + 1/25 और 1/18 + 1/28, 1/12 नहीं हैं)।','csat-l4-s09-qa-tw-two-taps-ten-hours-apart','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','Five odd numbers, not necessarily different, are added together. Which one of the following could be their total?','पाँच विषम संख्याएँ, आवश्यक नहीं कि अलग-अलग हों, जोड़ी जाती हैं। निम्नलिखित में से कौन-सा उनका योग हो सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 17}'::jsonb,'[{"id": "a", "body": "35", "body_hi": "35", "isCorrect": true}, {"id": "b", "body": "40", "body_hi": "40", "isCorrect": false}, {"id": "c", "body": "50", "body_hi": "50", "isCorrect": false}, {"id": "d", "body": "60", "body_hi": "60", "isCorrect": false}]'::jsonb,2.5,0.83,'Two odd numbers make an even number, so four of them make an even total, and the fifth makes it odd again. A sum of five odd numbers is always odd, and of the options only 35 is odd (for example 7 + 7 + 7 + 7 + 7). 40, 50 and 60 are even, so no five odd numbers can add up to any of them.','दो विषम संख्याएँ मिलकर सम बनती हैं, इसलिए चार का योग सम होता है, और पाँचवीं उसे फिर विषम बना देती है। पाँच विषम संख्याओं का योग सदा विषम होता है, और विकल्पों में केवल 35 विषम है (उदाहरण के लिए 7 + 7 + 7 + 7 + 7)। 40, 50 और 60 सम हैं, इसलिए कोई पाँच विषम संख्याएँ जुड़कर इनमें से कोई नहीं बना सकतीं।','csat-l4-s09-qa-nt-five-odd-numbers-added','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','A quiz has four questions, each to be answered True (T) or False (F). Three students answered as follows, and their scores (one mark for each correct answer) are given.
- Asha: T T F F, score 3
- Bina: T F T F, score 3
- Chetan: F T T T, score 2
What is the correct answer key, from question 1 to question 4?','एक प्रश्नोत्तरी में चार प्रश्न हैं, जिनमें से हर एक का उत्तर सत्य (T) या असत्य (F) देना है। तीन विद्यार्थियों ने नीचे दिए अनुसार उत्तर दिए, और उनके अंक (हर सही उत्तर का एक अंक) दिए गए हैं।
- आशा: T T F F, अंक 3
- बीना: T F T F, अंक 3
- चेतन: F T T T, अंक 2
प्रश्न 1 से प्रश्न 4 तक सही उत्तर-कुंजी क्या है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 18}'::jsonb,'[{"id": "a", "body": "T T F F", "body_hi": "T T F F", "isCorrect": false}, {"id": "b", "body": "T F T F", "body_hi": "T F T F", "isCorrect": false}, {"id": "c", "body": "F T T F", "body_hi": "F T T F", "isCorrect": false}, {"id": "d", "body": "T T T F", "body_hi": "T T T F", "isCorrect": true}]'::jsonb,2.5,0.83,'Asha and Bina agree on questions 1 and 4 and disagree on 2 and 3, so on 2 and 3 exactly one of them is right each time -- two marks between them. They have 6 marks together, so both must be right on 1 and 4: the key starts T and ends F. Chetan answered F to question 1 and T to question 4, both wrong, so his 2 marks come from questions 2 and 3: both are T. The key is T T T F (check: Asha 3, Bina 3, Chetan 2). T T F F and T F T F are Asha''s and Bina''s own answers, which would give them 4 marks; F T T F would give Asha only 2.','आशा और बीना प्रश्न 1 और 4 पर सहमत हैं और 2 तथा 3 पर असहमत, इसलिए 2 और 3 पर हर बार उनमें से ठीक एक सही है -- दोनों के मिलाकर दो अंक। उनके मिलाकर 6 अंक हैं, इसलिए दोनों 1 और 4 पर सही होंगे: कुंजी T से शुरू होकर F पर ख़त्म होती है। चेतन ने प्रश्न 1 का F और प्रश्न 4 का T उत्तर दिया, दोनों ग़लत, इसलिए उसके 2 अंक प्रश्न 2 और 3 से हैं: दोनों T हैं। कुंजी T T T F है (जाँच: आशा 3, बीना 3, चेतन 2)। T T F F और T F T F आशा और बीना के अपने उत्तर हैं, जिनसे उन्हें 4 अंक मिलते; F T T F से आशा को केवल 2 मिलते।','csat-l4-s09-lr-sa-a-quiz-s-answer-key-read-back-from-three-scores','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','If prices rise by 7% every year, roughly how many years will it take for prices to double?','यदि मूल्य हर वर्ष 7% बढ़ें, तो मूल्यों को दोगुना होने में मोटे तौर पर कितने वर्ष लगेंगे?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 19}'::jsonb,'[{"id": "a", "body": "7", "body_hi": "7", "isCorrect": false}, {"id": "b", "body": "10", "body_hi": "10", "isCorrect": true}, {"id": "c", "body": "14", "body_hi": "14", "isCorrect": false}, {"id": "d", "body": "15", "body_hi": "15", "isCorrect": false}]'::jsonb,2.5,0.83,'The rise compounds: 1.07 multiplied by itself 10 times is about 1.97, so prices roughly double in 10 years. A handy rule: the doubling time is about 70 divided by the yearly percentage, here 70 ÷ 7 = 10. 14 years assumes the rise does not compound (100 ÷ 7 ≈ 14.3); 7 confuses the rate with the time; 15 has no basis.','बढ़त चक्रवृद्धि होती है: 1.07 को स्वयं से 10 बार गुणा करने पर लगभग 1.97 मिलता है, इसलिए मूल्य मोटे तौर पर 10 वर्ष में दोगुने होते हैं। एक सरल नियम: दोगुना होने का समय लगभग 70 बटा वार्षिक प्रतिशत, यहाँ 70 ÷ 7 = 10। 14 वर्ष मानता है कि बढ़त चक्रवृद्धि नहीं होती (100 ÷ 7 ≈ 14.3); 7 दर को समय से भ्रमित करता है; 15 का कोई आधार नहीं।','csat-l4-s09-qa-pp-prices-that-double','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1793 Lord Cornwallis introduced the Permanent Settlement in Bengal. The zamindars were recognised as owners of the land, and the revenue each had to pay to the East India Company was fixed for ever. The Company hoped for a steady income it could count on, and expected that landlords secure in their property, and sure that any increase in output would be theirs, would invest in improving the land. Things turned out differently. The revenue was set so high that many zamindars failed to pay in the early years, and their estates were auctioned. Later, as cultivation spread and prices rose, the fixed demand became light, but the gains went largely to zamindars and a chain of intermediaries below them, while the cultivators, with weak rights, were squeezed. The Company, for its part, could not raise its revenue as the land grew more productive.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1793 में लॉर्ड कॉर्नवालिस ने बंगाल में स्थायी बंदोबस्त लागू किया। ज़मींदारों को भूमि का स्वामी माना गया, और हर एक को ईस्ट इंडिया कंपनी को जो राजस्व देना था, वह सदा के लिए तय कर दिया गया। कंपनी को एक स्थिर आय की आशा थी जिस पर वह भरोसा कर सके, और उसकी अपेक्षा थी कि अपनी संपत्ति के प्रति आश्वस्त, और यह जानते हुए कि उत्पादन की कोई भी वृद्धि उनकी अपनी होगी, ज़मींदार भूमि सुधारने में निवेश करेंगे। परिणाम अलग निकले। राजस्व इतना ऊँचा तय किया गया कि शुरुआती वर्षों में बहुत-से ज़मींदार भुगतान नहीं कर सके, और उनकी ज़मींदारियाँ नीलाम हुईं। बाद में, जैसे-जैसे खेती फैली और मूल्य बढ़े, तय माँग हल्की हो गई, पर लाभ अधिकतर ज़मींदारों और उनके नीचे बिचौलियों की एक कड़ी को गया, जबकि कमज़ोर अधिकारों वाले काश्तकार पिसते रहे। कंपनी, अपनी ओर से, भूमि के अधिक उपजाऊ होने के साथ अपना राजस्व नहीं बढ़ा सकी।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p03", "csat_order": 20}'::jsonb,'[{"id": "a", "body": "The revenue demand was set so low that the Company soon ran short of the income it needed to govern.", "body_hi": "राजस्व की माँग इतनी कम रखी गई कि कंपनी को शासन चलाने के लिए आवश्यक आय की जल्दी ही कमी पड़ गई।", "isCorrect": false}, {"id": "b", "body": "The fixed revenue failed its aims, and its gains went to those above the cultivators.", "body_hi": "तय राजस्व अपने उद्देश्यों में विफल रहा, और उसके लाभ काश्तकारों के ऊपर वालों को गए।", "isCorrect": true}, {"id": "c", "body": "The Settlement took the land away from the zamindars and gave it to the Company.", "body_hi": "बंदोबस्त ने ज़मींदारों से भूमि लेकर कंपनी को दे दी।", "isCorrect": false}, {"id": "d", "body": "The cultivators of Bengal were the chief gainers when prices and output rose.", "body_hi": "मूल्य और उत्पादन बढ़ने पर बंगाल के काश्तकार ही मुख्य लाभार्थी रहे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage sets out what the Permanent Settlement was meant to achieve -- a steady income and improving landlords -- and shows how it turned out: auctions at first, then gains captured by zamindars and intermediaries, squeezed cultivators, and a Company unable to share in rising output. It says the early demand was too high, not too low; the zamindars were recognised as owners, not stripped of their land; and the gains went to zamindars and intermediaries, not to the cultivators.','परिच्छेद बताता है कि स्थायी बंदोबस्त से क्या पाने की आशा थी -- स्थिर आय और सुधार करने वाले ज़मींदार -- और दिखाता है कि परिणाम क्या रहा: पहले नीलामियाँ, फिर ज़मींदारों और बिचौलियों द्वारा हथियाए गए लाभ, पिसते काश्तकार, और बढ़ते उत्पादन में हिस्सा न पा सकने वाली कंपनी। वह कहता है कि शुरुआती माँग बहुत ऊँची थी, नीची नहीं; ज़मींदारों को स्वामी माना गया, उनसे भूमि छीनी नहीं गई; और लाभ ज़मींदारों और बिचौलियों को गया, काश्तकारों को नहीं।','csat-l4-s09-rc-p03-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1793 Lord Cornwallis introduced the Permanent Settlement in Bengal. The zamindars were recognised as owners of the land, and the revenue each had to pay to the East India Company was fixed for ever. The Company hoped for a steady income it could count on, and expected that landlords secure in their property, and sure that any increase in output would be theirs, would invest in improving the land. Things turned out differently. The revenue was set so high that many zamindars failed to pay in the early years, and their estates were auctioned. Later, as cultivation spread and prices rose, the fixed demand became light, but the gains went largely to zamindars and a chain of intermediaries below them, while the cultivators, with weak rights, were squeezed. The Company, for its part, could not raise its revenue as the land grew more productive.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1793 में लॉर्ड कॉर्नवालिस ने बंगाल में स्थायी बंदोबस्त लागू किया। ज़मींदारों को भूमि का स्वामी माना गया, और हर एक को ईस्ट इंडिया कंपनी को जो राजस्व देना था, वह सदा के लिए तय कर दिया गया। कंपनी को एक स्थिर आय की आशा थी जिस पर वह भरोसा कर सके, और उसकी अपेक्षा थी कि अपनी संपत्ति के प्रति आश्वस्त, और यह जानते हुए कि उत्पादन की कोई भी वृद्धि उनकी अपनी होगी, ज़मींदार भूमि सुधारने में निवेश करेंगे। परिणाम अलग निकले। राजस्व इतना ऊँचा तय किया गया कि शुरुआती वर्षों में बहुत-से ज़मींदार भुगतान नहीं कर सके, और उनकी ज़मींदारियाँ नीलाम हुईं। बाद में, जैसे-जैसे खेती फैली और मूल्य बढ़े, तय माँग हल्की हो गई, पर लाभ अधिकतर ज़मींदारों और उनके नीचे बिचौलियों की एक कड़ी को गया, जबकि कमज़ोर अधिकारों वाले काश्तकार पिसते रहे। कंपनी, अपनी ओर से, भूमि के अधिक उपजाऊ होने के साथ अपना राजस्व नहीं बढ़ा सकी।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["A revenue demand fixed in money grows lighter as prices rise.", "The early auctions of estates suggest that the revenue demand was at first too heavy."], "statements_hi": ["पैसे में तय राजस्व-माँग मूल्य बढ़ने के साथ हल्की होती जाती है।", "ज़मींदारियों की शुरुआती नीलामियाँ संकेत देती हैं कि राजस्व-माँग शुरू में बहुत भारी थी।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p03", "csat_order": 21}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. 1: the passage says that as prices rose the fixed demand ''became light'' -- a sum fixed in money is worth less as prices climb. 2: many zamindars failed to pay in the early years and lost their estates at auction, which shows the demand was at first too heavy for them.','दोनों वैध हैं। 1: परिच्छेद कहता है कि मूल्य बढ़ने पर तय माँग ''हल्की हो गई'' -- पैसे में तय राशि का मूल्य मूल्यों के चढ़ने के साथ घटता है। 2: शुरुआती वर्षों में बहुत-से ज़मींदार भुगतान नहीं कर सके और नीलामी में अपनी ज़मींदारियाँ खो बैठे, जो दिखाता है कि माँग शुरू में उनके लिए बहुत भारी थी।','csat-l4-s09-rc-p03-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','Starting from the number 1, at each step you may either double the number or add 1 to it. What is the least number of steps needed to reach exactly 100?','संख्या 1 से शुरू करके, हर क़दम पर आप या तो संख्या को दोगुना कर सकते हैं या उसमें 1 जोड़ सकते हैं। ठीक 100 तक पहुँचने के लिए कम से कम कितने क़दम चाहिए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 22}'::jsonb,'[{"id": "a", "body": "7", "body_hi": "7", "isCorrect": false}, {"id": "b", "body": "8", "body_hi": "8", "isCorrect": true}, {"id": "c", "body": "9", "body_hi": "9", "isCorrect": false}, {"id": "d", "body": "10", "body_hi": "10", "isCorrect": false}]'::jsonb,2.5,0.83,'Work backwards from 100, halving whenever the number is even and taking 1 away when it is odd: 100, 50, 25, 24, 12, 6, 3, 2, 1. That is 8 steps, and going forward: 1, 2, 3, 6, 12, 24, 25, 50, 100. Halving whenever possible is never worse, so 8 is the least. Seven steps are one too few: even doubling every time gives 1, 2, 4, ..., 128, and each ''add 1'' used instead of a doubling lands well below 100. 9 and 10 steps are possible but not the least.','100 से पीछे की ओर चलें, संख्या सम हो तो आधी करें और विषम हो तो 1 घटाएँ: 100, 50, 25, 24, 12, 6, 3, 2, 1। यह 8 क़दम हैं, और आगे की ओर: 1, 2, 3, 6, 12, 24, 25, 50, 100। जहाँ संभव हो आधा करना कभी बदतर नहीं, इसलिए 8 सबसे कम है। सात क़दम एक कम हैं: हर बार दोगुना करने पर भी 1, 2, 4, ..., 128 मिलता है, और दोगुना करने के बदले लिया गया हर ''1 जोड़ो'' 100 से काफ़ी नीचे रह जाता है। 9 और 10 क़दम संभव हैं पर सबसे कम नहीं।','csat-l4-s09-qa-ph-1-to-100-by-doubling-or-adding-one','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','medium','Statements: All squares are rectangles. No rectangle is a circle. Some of the shapes on the board are squares.

Which of the following conclusions follow(s) from the statements?','कथन: सभी वर्ग आयत हैं। कोई आयत वृत्त नहीं है। बोर्ड पर की कुछ आकृतियाँ वर्ग हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["No square is a circle.", "Some of the shapes on the board are rectangles."], "statements_hi": ["कोई वर्ग वृत्त नहीं है।", "बोर्ड पर की कुछ आकृतियाँ आयत हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s09", "csat_order": 23}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": false}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": false}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": true}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Both follow. I: every square is a rectangle and no rectangle is a circle, so no square can be a circle. II: some shapes on the board are squares, and every square is a rectangle, so those shapes are rectangles.','दोनों निकलते हैं। I: हर वर्ग एक आयत है और कोई आयत वृत्त नहीं, इसलिए कोई वर्ग वृत्त नहीं हो सकता। II: बोर्ड पर की कुछ आकृतियाँ वर्ग हैं, और हर वर्ग आयत है, इसलिए वे आकृतियाँ आयत हैं।','csat-l4-s09-lr-sy-squares-rectangles-and-circles','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','easy','Which number in the series 2, 5, 10, 17, 26, 38, 50 does not fit the pattern?','श्रेणी 2, 5, 10, 17, 26, 38, 50 में कौन-सी संख्या पैटर्न में नहीं बैठती?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 24}'::jsonb,'[{"id": "a", "body": "10", "body_hi": "10", "isCorrect": false}, {"id": "b", "body": "17", "body_hi": "17", "isCorrect": false}, {"id": "c", "body": "26", "body_hi": "26", "isCorrect": false}, {"id": "d", "body": "38", "body_hi": "38", "isCorrect": true}]'::jsonb,2.5,0.83,'The terms are one more than the squares: 1 + 1, 4 + 1, 9 + 1, 16 + 1, 25 + 1, then 36 + 1 = 37 and 49 + 1 = 50. So 38 should be 37. (The gaps 3, 5, 7, 9 should go on 11, 13; the given gaps 12 and 12 break the pattern at 38.) 10, 17 and 26 all fit as 3² + 1, 4² + 1 and 5² + 1.','पद वर्गों से एक अधिक हैं: 1 + 1, 4 + 1, 9 + 1, 16 + 1, 25 + 1, फिर 36 + 1 = 37 और 49 + 1 = 50। इसलिए 38 को 37 होना चाहिए। (अंतर 3, 5, 7, 9 के बाद 11, 13 आने चाहिए; दिए गए अंतर 12 और 12, 38 पर पैटर्न तोड़ते हैं।) 10, 17 और 26, 3² + 1, 4² + 1 और 5² + 1 के रूप में ठीक बैठते हैं।','csat-l4-s09-qa-ss-a-wrong-term-among-n-squared-plus-1','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the remainder when 7001 × 7002 × 7003 is divided by 7000?','7001 × 7002 × 7003 को 7000 से भाग देने पर शेषफल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 25}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "b", "body": "3", "body_hi": "3", "isCorrect": false}, {"id": "c", "body": "6", "body_hi": "6", "isCorrect": true}, {"id": "d", "body": "24", "body_hi": "24", "isCorrect": false}]'::jsonb,2.5,0.83,'Each factor can be replaced by its own remainder on division by 7000: 7001 leaves 1, 7002 leaves 2 and 7003 leaves 3. So the product leaves the same remainder as 1 × 2 × 3 = 6, with no need to multiply the large numbers. (Adding the remainders, 1 + 2 + 3, also gives 6 here, but only by coincidence: the rule is to multiply them.) 3 is the last remainder alone; 24 = 2 × 3 × 4 takes each remainder one too high; 1 is the first remainder alone.','हर गुणनखंड को 7000 से भाग देने पर बचे उसके अपने शेषफल से बदला जा सकता है: 7001 से 1, 7002 से 2 और 7003 से 3 बचता है। इसलिए गुणनफल का शेषफल वही है जो 1 × 2 × 3 = 6 का, बड़ी संख्याओं का गुणा किए बिना। (शेषफलों को जोड़ने, 1 + 2 + 3, से भी यहाँ 6 मिलता है, पर केवल संयोग से: नियम उन्हें गुणा करने का है।) 3 केवल अंतिम शेषफल है; 24 = 2 × 3 × 4 हर शेषफल को एक अधिक ले लेता है; 1 केवल पहला शेषफल है।','csat-l4-s09-qa-nt-a-product-reduced-before-dividing','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Blood Relation','mcq','hard','In a code, ''P × Q'' means P is the father of Q; ''P + Q'' means P is the mother of Q; ''P - Q'' means P is the sister of Q; and ''P ÷ Q'' means P is the brother of Q. Which one of the following means that M is the grandmother of T?','एक कूट में ''P × Q'' का अर्थ है P, Q का पिता है; ''P + Q'' का अर्थ है P, Q की माँ है; ''P - Q'' का अर्थ है P, Q की बहन है; और ''P ÷ Q'' का अर्थ है P, Q का भाई है। निम्नलिखित में से किसका अर्थ है कि M, T की दादी/नानी है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 26}'::jsonb,'[{"id": "a", "body": "M × K + T", "body_hi": "M × K + T", "isCorrect": false}, {"id": "b", "body": "M - K × T", "body_hi": "M - K × T", "isCorrect": false}, {"id": "c", "body": "M + K × T", "body_hi": "M + K × T", "isCorrect": true}, {"id": "d", "body": "M + K - T", "body_hi": "M + K - T", "isCorrect": false}]'::jsonb,2.5,0.83,'M + K × T reads: M is the mother of K, and K is the father of T -- so M is T''s father''s mother, T''s grandmother. M × K + T makes M the father of T''s mother, a grandfather; M - K × T makes M the sister of T''s father, an aunt; and M + K - T makes M the mother of K, who is T''s sister, so M is T''s mother.','M + K × T का अर्थ है: M, K की माँ है, और K, T का पिता है -- इसलिए M, T के पिता की माँ, यानी T की दादी है। M × K + T में M, T की माँ का पिता, यानी नाना बनता है; M - K × T में M, T के पिता की बहन, यानी बुआ; और M + K - T में M, K की माँ है, जो T की बहन है, इसलिए M, T की माँ है।','csat-l4-s09-lr-br-a-grandmother-written-in-symbols','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1912 the German scientist Alfred Wegener proposed that the continents had once been joined in a single landmass, which he later called Pangaea, and had since drifted apart. He pointed to the way the coasts of South America and Africa fit together, to matching rocks and fossils of the same land plants and animals on continents now separated by oceans, and to traces of ancient glaciers in regions that are now tropical. Most geologists rejected the idea for decades. The evidence was striking, but Wegener could not explain what force could push continents through the solid ocean floor, and the forces he suggested were far too weak. Only in the 1960s, when studies of the sea floor showed it spreading outwards from ridges in the middle of the oceans, did a mechanism emerge, and continental drift became part of the theory of plate tectonics.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1912 में जर्मन वैज्ञानिक आल्फ़्रेड वेगनर ने प्रस्ताव रखा कि महाद्वीप कभी एक ही भूखंड में जुड़े थे, जिसे उन्होंने बाद में पैंजिया कहा, और तब से अलग-अलग खिसक गए हैं। उन्होंने दक्षिण अमेरिका और अफ़्रीका के तटों के आपस में बैठने, आज महासागरों से अलग महाद्वीपों पर मिलती-जुलती चट्टानों और एक ही स्थलीय पौधों और जीवों के जीवाश्मों, और आज उष्णकटिबंधीय क्षेत्रों में प्राचीन हिमनदों के चिह्नों की ओर संकेत किया। अधिकांश भूवैज्ञानिकों ने दशकों तक यह विचार अस्वीकार किया। प्रमाण प्रभावशाली थे, पर वेगनर यह नहीं समझा सके कि कौन-सा बल महाद्वीपों को ठोस महासागरीय तल के बीच से धकेल सकता है, और उनके सुझाए बल बहुत ही कमज़ोर थे। केवल 1960 के दशक में, जब समुद्र-तल के अध्ययनों ने दिखाया कि वह महासागरों के बीच की कटकों से बाहर की ओर फैल रहा है, एक तंत्र सामने आया, और महाद्वीपीय विस्थापन प्लेट विवर्तनिकी के सिद्धांत का भाग बन गया।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p04", "csat_order": 27}'::jsonb,'[{"id": "a", "body": "Wegener''s evidence for drifting continents was so weak that geologists were right to ignore it.", "body_hi": "खिसकते महाद्वीपों के लिए वेगनर के प्रमाण इतने कमज़ोर थे कि भूवैज्ञानिकों का उन्हें अनदेखा करना ठीक था।", "isCorrect": false}, {"id": "b", "body": "Geologists accepted Wegener''s idea at once because the coasts of two continents fit together.", "body_hi": "भूवैज्ञानिकों ने वेगनर का विचार तुरंत स्वीकार कर लिया क्योंकि दो महाद्वीपों के तट आपस में बैठते थे।", "isCorrect": false}, {"id": "c", "body": "Wegener correctly identified the force that moves the continents across the surface of the Earth.", "body_hi": "वेगनर ने वह बल सही-सही पहचाना जो पृथ्वी की सतह पर महाद्वीपों को खिसकाता है।", "isCorrect": false}, {"id": "d", "body": "Drift was doubted for want of a mechanism, not evidence, until sea-floor studies gave one.", "body_hi": "विस्थापन प्रमाण की नहीं, तंत्र की कमी से संदिग्ध रहा, जब तक समुद्र-तल ने तंत्र नहीं दिया।", "isCorrect": true}]'::jsonb,2.5,0.83,'Wegener''s evidence was strong, but his idea was rejected for decades because he had no convincing mechanism; it was accepted once sea-floor spreading supplied one. The passage calls his evidence striking, not weak; it says the idea was rejected, not quickly accepted; and it says the forces he proposed were far too weak, not that he found the right one.','वेगनर के प्रमाण मज़बूत थे, पर उनका विचार दशकों तक अस्वीकार रहा क्योंकि उनके पास कोई विश्वसनीय तंत्र नहीं था; समुद्र-तल के फैलाव ने जब तंत्र दिया, तब उसे स्वीकार किया गया। परिच्छेद उनके प्रमाणों को प्रभावशाली कहता है, कमज़ोर नहीं; वह कहता है कि विचार अस्वीकार हुआ, जल्दी स्वीकार नहीं; और वह कहता है कि उनके सुझाए बल बहुत कमज़ोर थे, यह नहीं कि उन्होंने सही बल खोज लिया।','csat-l4-s09-rc-p04-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1912 the German scientist Alfred Wegener proposed that the continents had once been joined in a single landmass, which he later called Pangaea, and had since drifted apart. He pointed to the way the coasts of South America and Africa fit together, to matching rocks and fossils of the same land plants and animals on continents now separated by oceans, and to traces of ancient glaciers in regions that are now tropical. Most geologists rejected the idea for decades. The evidence was striking, but Wegener could not explain what force could push continents through the solid ocean floor, and the forces he suggested were far too weak. Only in the 1960s, when studies of the sea floor showed it spreading outwards from ridges in the middle of the oceans, did a mechanism emerge, and continental drift became part of the theory of plate tectonics.

On the passage''s account, which one of the following would most likely have won geologists over to Wegener''s idea much earlier?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1912 में जर्मन वैज्ञानिक आल्फ़्रेड वेगनर ने प्रस्ताव रखा कि महाद्वीप कभी एक ही भूखंड में जुड़े थे, जिसे उन्होंने बाद में पैंजिया कहा, और तब से अलग-अलग खिसक गए हैं। उन्होंने दक्षिण अमेरिका और अफ़्रीका के तटों के आपस में बैठने, आज महासागरों से अलग महाद्वीपों पर मिलती-जुलती चट्टानों और एक ही स्थलीय पौधों और जीवों के जीवाश्मों, और आज उष्णकटिबंधीय क्षेत्रों में प्राचीन हिमनदों के चिह्नों की ओर संकेत किया। अधिकांश भूवैज्ञानिकों ने दशकों तक यह विचार अस्वीकार किया। प्रमाण प्रभावशाली थे, पर वेगनर यह नहीं समझा सके कि कौन-सा बल महाद्वीपों को ठोस महासागरीय तल के बीच से धकेल सकता है, और उनके सुझाए बल बहुत ही कमज़ोर थे। केवल 1960 के दशक में, जब समुद्र-तल के अध्ययनों ने दिखाया कि वह महासागरों के बीच की कटकों से बाहर की ओर फैल रहा है, एक तंत्र सामने आया, और महाद्वीपीय विस्थापन प्लेट विवर्तनिकी के सिद्धांत का भाग बन गया।

परिच्छेद के अनुसार, निम्नलिखित में से क्या भूवैज्ञानिकों को बहुत पहले वेगनर के विचार की ओर ला सकता था?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p04", "csat_order": 28}'::jsonb,'[{"id": "a", "body": "A force, shown to exist, strong enough to move whole continents", "body_hi": "पूरे महाद्वीपों को खिसका सकने वाला एक सिद्ध बल", "isCorrect": true}, {"id": "b", "body": "More fossils of the same animal found on two separate continents", "body_hi": "दो अलग महाद्वीपों पर एक ही जीव के और जीवाश्म", "isCorrect": false}, {"id": "c", "body": "Fresh traces of ancient glaciers found in other tropical regions", "body_hi": "दूसरे उष्णकटिबंधीय क्षेत्रों में प्राचीन हिमनदों के नए चिह्न", "isCorrect": false}, {"id": "d", "body": "A still closer match between the coastlines of two continents", "body_hi": "दो महाद्वीपों के तटों के बीच और भी सटीक मेल", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says the idea was rejected because Wegener could not explain what force could move continents, and that it was accepted once sea-floor spreading supplied a mechanism. A convincing mechanism, found earlier, is therefore what would most likely have changed minds. More fossils, more glacier traces or a closer fit of coastlines would add to evidence the passage already calls striking -- evidence that, by itself, did not persuade.','परिच्छेद कहता है कि विचार इसलिए अस्वीकार हुआ कि वेगनर नहीं समझा सके कि कौन-सा बल महाद्वीपों को खिसका सकता है, और कि समुद्र-तल के फैलाव ने जब तंत्र दिया तब उसे स्वीकार किया गया। इसलिए पहले मिला एक विश्वसनीय तंत्र ही सबसे संभवतः मत बदलता। अधिक जीवाश्म, हिमनदों के अधिक चिह्न या तटों का और सटीक मेल उन प्रमाणों में जुड़ते जिन्हें परिच्छेद पहले ही प्रभावशाली कहता है -- ऐसे प्रमाण जो अपने आप में राज़ी नहीं कर सके।','csat-l4-s09-rc-p04-what-would-have-persuaded-sooner','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','What is the value of 8^(2/3) + 16^(-1/4) × 32^(2/5)?','8^(2/3) + 16^(-1/4) × 32^(2/5) का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 29}'::jsonb,'[{"id": "a", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "b", "body": "4.5", "body_hi": "4.5", "isCorrect": false}, {"id": "c", "body": "5", "body_hi": "5", "isCorrect": false}, {"id": "d", "body": "6", "body_hi": "6", "isCorrect": true}]'::jsonb,2.5,0.83,'8^(2/3) = (the cube root of 8)² = 2² = 4. 16^(-1/4) = 1 ÷ (the fourth root of 16) = 1/2. 32^(2/5) = (the fifth root of 32)² = 2² = 4. So the value is 4 + (1/2) × 4 = 6, the multiplication being done before the addition. 5 forgets to square the fifth root of 32 (4 + 1/2 × 2); 4.5 forgets the last factor (4 + 1/2); 2 keeps only the product and drops 8^(2/3).','8^(2/3) = (8 का घनमूल)² = 2² = 4। 16^(-1/4) = 1 ÷ (16 का चौथा मूल) = 1/2। 32^(2/5) = (32 का पाँचवाँ मूल)² = 2² = 4। अतः मान 4 + (1/2) × 4 = 6 है, जोड़ से पहले गुणा करके। 5, 32 के पाँचवें मूल का वर्ग करना भूल जाता है (4 + 1/2 × 2); 4.5 अंतिम गुणनखंड भूल जाता है (4 + 1/2); 2 केवल गुणनफल रखता है और 8^(2/3) छोड़ देता है।','csat-l4-s09-qa-nt-fractional-and-negative-indices','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','hard','In a town, 30% of the people were below the poverty line. Five years later the town''s population is 10% larger, and 25% of the people are below the line. How has the number of people below the line changed?','एक कस्बे में 30% लोग ग़रीबी रेखा के नीचे थे। पाँच वर्ष बाद कस्बे की जनसंख्या 10% अधिक है, और 25% लोग रेखा के नीचे हैं। रेखा के नीचे के लोगों की संख्या कैसे बदली है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 30}'::jsonb,'[{"id": "a", "body": "It has fallen by about 8.3%", "body_hi": "यह लगभग 8.3% घटी है", "isCorrect": true}, {"id": "b", "body": "It has fallen by 5%", "body_hi": "यह 5% घटी है", "isCorrect": false}, {"id": "c", "body": "It has fallen by about 16.7%", "body_hi": "यह लगभग 16.7% घटी है", "isCorrect": false}, {"id": "d", "body": "It has risen by 10%", "body_hi": "यह 10% बढ़ी है", "isCorrect": false}]'::jsonb,2.5,0.83,'Take 100 people at first: 30 below the line. Five years later there are 110 people, and 25% of 110 = 27.5 are below it. The number has fallen from 30 to 27.5, by 2.5 ÷ 30 ≈ 8.3%. ''Fallen by 5%'' mistakes the drop of 5 percentage points for a 5% drop; 16.7% (5 ÷ 30) ignores the growth in population; ''risen by 10%'' ignores the fall in the share.','आरंभ में 100 लोग लें: 30 रेखा के नीचे। पाँच वर्ष बाद 110 लोग हैं, और 110 का 25% = 27.5 रेखा के नीचे हैं। संख्या 30 से घटकर 27.5 हुई, यानी 2.5 ÷ 30 ≈ 8.3%। ''5% घटी'' 5 प्रतिशत अंक की गिरावट को 5% की गिरावट समझ लेता है; 16.7% (5 ÷ 30) जनसंख्या की वृद्धि की अनदेखी करता है; ''10% बढ़ी'' हिस्से में गिरावट की अनदेखी करता है।','csat-l4-s09-qa-pp-people-below-a-line-in-a-growing-town','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Direction & Distance','mcq','hard','A large mirror hangs on the north wall of a room. Ravi stands facing the mirror and holds up a card on which an arrow points east. In which direction does the arrow in the mirror''s image point?','एक कमरे की उत्तरी दीवार पर एक बड़ा दर्पण टँगा है। रवि दर्पण की ओर मुँह करके खड़ा है और एक कार्ड उठाता है जिस पर बना तीर पूर्व की ओर है। दर्पण के प्रतिबिंब में तीर किस दिशा की ओर है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 31}'::jsonb,'[{"id": "a", "body": "West", "body_hi": "पश्चिम", "isCorrect": false}, {"id": "b", "body": "East", "body_hi": "पूर्व", "isCorrect": true}, {"id": "c", "body": "North", "body_hi": "उत्तर", "isCorrect": false}, {"id": "d", "body": "South", "body_hi": "दक्षिण", "isCorrect": false}]'::jsonb,2.5,0.83,'A flat mirror reverses only the direction at right angles to it -- here north and south, so that Ravi''s image faces south, back towards him. Directions along the mirror are unchanged: an arrow pointing east, to Ravi''s right, is seen in the mirror still pointing east, to Ravi''s right. West is the common slip of thinking a mirror swaps left and right; north and south would need the arrow to point towards or away from the mirror.','समतल दर्पण केवल अपने लंबवत दिशा को उलटता है -- यहाँ उत्तर और दक्षिण, जिससे रवि का प्रतिबिंब दक्षिण की ओर, उसी की ओर, देखता है। दर्पण के साथ-साथ की दिशाएँ नहीं बदलतीं: पूर्व, यानी रवि के दाईं ओर, इशारा करता तीर दर्पण में भी पूर्व की ओर, रवि के दाईं ओर, दिखता है। पश्चिम वह आम भूल है कि दर्पण बाएँ-दाएँ बदल देता है; उत्तर या दक्षिण के लिए तीर को दर्पण की ओर या उससे दूर इशारा करना होता।','csat-l4-s09-lr-dd-an-arrow-seen-in-a-mirror-on-the-north-wall','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','medium','Three solid metal cubes with edges of 3 cm, 4 cm and 5 cm are melted and recast into a single cube, with no metal lost. What is the edge of the new cube?','3 सेमी, 4 सेमी और 5 सेमी किनारों वाले धातु के तीन ठोस घनों को पिघलाकर, बिना धातु गँवाए, एक घन में ढाला जाता है। नए घन का किनारा क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 32}'::jsonb,'[{"id": "a", "body": "6 cm", "body_hi": "6 सेमी", "isCorrect": true}, {"id": "b", "body": "8 cm", "body_hi": "8 सेमी", "isCorrect": false}, {"id": "c", "body": "12 cm", "body_hi": "12 सेमी", "isCorrect": false}, {"id": "d", "body": "216 cm", "body_hi": "216 सेमी", "isCorrect": false}]'::jsonb,2.5,0.83,'Melting keeps the volume: 3³ + 4³ + 5³ = 27 + 64 + 125 = 216 cm³, and 216 = 6³, so the new edge is 6 cm. 12 cm adds the edges, as if lengths rather than volumes were kept; 216 is the volume in cm³, not an edge; 8 cm has no basis.','पिघलाने से आयतन वही रहता है: 3³ + 4³ + 5³ = 27 + 64 + 125 = 216 घन सेमी, और 216 = 6³, इसलिए नया किनारा 6 सेमी है। 12 सेमी किनारों को जोड़ता है, मानो आयतन के बजाय लंबाइयाँ बनी रहती हों; 216 घन सेमी में आयतन है, किनारा नहीं; 8 सेमी का कोई आधार नहीं।','csat-l4-s09-qa-gm-cubes-melted-into-one','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the remainder when 2²⁰²⁷ + 3²⁰²⁷ is divided by 5?','2²⁰²⁷ + 3²⁰²⁷ को 5 से भाग देने पर शेषफल क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 33}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": true}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "d", "body": "3", "body_hi": "3", "isCorrect": false}]'::jsonb,2.5,0.83,'For an odd power n, aⁿ + bⁿ is always divisible by a + b (for example a³ + b³ = (a + b)(a² - ab + b²)). Here a + b = 2 + 3 = 5 and 2027 is odd, so 2²⁰²⁷ + 3²⁰²⁷ is a multiple of 5: remainder 0. (Check with a small odd power: 2³ + 3³ = 35.) The other remainders come from working out only one of the two powers, or from treating the power as even, as in 2² + 3² = 13, which leaves 3.','विषम घात n के लिए aⁿ + bⁿ सदा a + b से विभाज्य होता है (उदाहरण के लिए a³ + b³ = (a + b)(a² - ab + b²))। यहाँ a + b = 2 + 3 = 5 और 2027 विषम है, इसलिए 2²⁰²⁷ + 3²⁰²⁷, 5 का गुणज है: शेषफल 0। (छोटी विषम घात से जाँचें: 2³ + 3³ = 35।) बाक़ी शेषफल दोनों में से केवल एक घात निकालने से, या घात को सम मानने से आते हैं, जैसे 2² + 3² = 13, जिससे 3 बचता है।','csat-l4-s09-qa-nt-two-odd-powers-divided-by-5','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1936 the economist John Maynard Keynes compared professional investment to a newspaper competition in which readers had to pick the six prettiest faces from a hundred photographs, the prize going to the reader whose choice came nearest to the average choice of all the competitors. To win, a reader should not pick the faces they personally found prettiest, nor even those they thought most people would find prettiest, but those they expected the others to expect to be most popular. In the same way, Keynes argued, investors buying shares for a quick profit try to guess not what a company is truly worth but what other investors will soon think it worth. Prices can then drift far from any sober estimate of value, driven by shifts of mood. The comparison does not mean that every investor behaves so: those who buy to hold for many years can ignore the crowd -- though, as Keynes noted, they may look foolish while they wait.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1936 में अर्थशास्त्री जॉन मेनार्ड कीन्स ने पेशेवर निवेश की तुलना एक अख़बार की प्रतियोगिता से की, जिसमें पाठकों को सौ तस्वीरों में से छह सबसे सुंदर चेहरे चुनने थे, और पुरस्कार उस पाठक को मिलना था जिसका चुनाव सभी प्रतियोगियों के औसत चुनाव के सबसे निकट हो। जीतने के लिए पाठक को वे चेहरे नहीं चुनने चाहिए जो उसे स्वयं सबसे सुंदर लगें, न वे भी जिन्हें वह सोचता है कि अधिकांश लोग सबसे सुंदर पाएँगे, बल्कि वे जिनके बारे में उसका अनुमान हो कि दूसरे उन्हें सबसे लोकप्रिय मानेंगे। कीन्स का तर्क था कि इसी तरह जल्दी लाभ के लिए शेयर ख़रीदने वाले निवेशक यह अनुमान लगाने का प्रयास करते हैं कि कोई कंपनी वास्तव में कितने की है, यह नहीं, बल्कि यह कि दूसरे निवेशक जल्दी ही उसे कितने का मानेंगे। तब मूल्य किसी भी संयत आकलन से बहुत दूर बह सकते हैं, मनोदशा के बदलावों से प्रेरित होकर। इस तुलना का अर्थ यह नहीं कि हर निवेशक ऐसा ही करता है: जो बरसों तक रखने के लिए ख़रीदते हैं वे भीड़ की अनदेखी कर सकते हैं -- यद्यपि, जैसा कीन्स ने कहा, प्रतीक्षा करते समय वे मूर्ख दिख सकते हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p05", "csat_order": 34}'::jsonb,'[{"id": "a", "body": "Share prices always settle at what companies are truly worth, whatever investors happen to feel.", "body_hi": "निवेशक जो भी महसूस करें, शेयरों के दाम सदा उसी पर टिकते हैं जितनी कंपनियाँ वास्तव में मूल्यवान हैं।", "isCorrect": false}, {"id": "b", "body": "Every investor, short-term or long-term, is bound to follow the mood of the crowd.", "body_hi": "हर निवेशक, अल्पकालिक हो या दीर्घकालिक, भीड़ की मनोदशा का अनुसरण करने को बाध्य है।", "isCorrect": false}, {"id": "c", "body": "Short-term investors guess others'' views, not true worth, so prices can stray from value.", "body_hi": "अल्पकालिक निवेशक मूल्य नहीं, दूसरों की सोच भाँपते हैं, इसलिए क़ीमतें मूल्य से भटक सकती हैं।", "isCorrect": true}, {"id": "d", "body": "The best way to judge a face is to pick the one that most other people will like.", "body_hi": "किसी चेहरे को आँकने का सबसे अच्छा ढंग वह चुनना है जो अधिकांश दूसरे लोगों को पसंद आए।", "isCorrect": false}]'::jsonb,2.5,0.83,'Keynes''s point is that short-term investors, like the contest''s players, guess what others will think rather than what something is worth, so prices can stray from value; the passage adds that long-term investors can stand apart. It says prices can drift far from value, so it does not claim they always match it; it says not every investor behaves so; and it is about markets, not about judging beauty.','कीन्स की बात यह है कि अल्पकालिक निवेशक, प्रतियोगिता के खिलाड़ियों की तरह, यह अनुमान लगाते हैं कि दूसरे क्या सोचेंगे, यह नहीं कि किसी चीज़ का मूल्य क्या है, इसलिए मूल्य वास्तविक मूल्य से भटक सकते हैं; परिच्छेद जोड़ता है कि दीर्घकालिक निवेशक अलग रह सकते हैं। वह कहता है कि मूल्य वास्तविक मूल्य से बहुत दूर बह सकते हैं, इसलिए वह यह दावा नहीं करता कि वे सदा मेल खाते हैं; वह कहता है कि हर निवेशक ऐसा नहीं करता; और वह बाज़ारों के बारे में है, सुंदरता आँकने के बारे में नहीं।','csat-l4-s09-rc-p05-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1936 the economist John Maynard Keynes compared professional investment to a newspaper competition in which readers had to pick the six prettiest faces from a hundred photographs, the prize going to the reader whose choice came nearest to the average choice of all the competitors. To win, a reader should not pick the faces they personally found prettiest, nor even those they thought most people would find prettiest, but those they expected the others to expect to be most popular. In the same way, Keynes argued, investors buying shares for a quick profit try to guess not what a company is truly worth but what other investors will soon think it worth. Prices can then drift far from any sober estimate of value, driven by shifts of mood. The comparison does not mean that every investor behaves so: those who buy to hold for many years can ignore the crowd -- though, as Keynes noted, they may look foolish while they wait.

A reader in the competition personally finds face 12 the prettiest, but expects that most competitors will expect face 40 to be the popular choice. On the passage''s reasoning, which of the two faces should the reader prefer, in order to win?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1936 में अर्थशास्त्री जॉन मेनार्ड कीन्स ने पेशेवर निवेश की तुलना एक अख़बार की प्रतियोगिता से की, जिसमें पाठकों को सौ तस्वीरों में से छह सबसे सुंदर चेहरे चुनने थे, और पुरस्कार उस पाठक को मिलना था जिसका चुनाव सभी प्रतियोगियों के औसत चुनाव के सबसे निकट हो। जीतने के लिए पाठक को वे चेहरे नहीं चुनने चाहिए जो उसे स्वयं सबसे सुंदर लगें, न वे भी जिन्हें वह सोचता है कि अधिकांश लोग सबसे सुंदर पाएँगे, बल्कि वे जिनके बारे में उसका अनुमान हो कि दूसरे उन्हें सबसे लोकप्रिय मानेंगे। कीन्स का तर्क था कि इसी तरह जल्दी लाभ के लिए शेयर ख़रीदने वाले निवेशक यह अनुमान लगाने का प्रयास करते हैं कि कोई कंपनी वास्तव में कितने की है, यह नहीं, बल्कि यह कि दूसरे निवेशक जल्दी ही उसे कितने का मानेंगे। तब मूल्य किसी भी संयत आकलन से बहुत दूर बह सकते हैं, मनोदशा के बदलावों से प्रेरित होकर। इस तुलना का अर्थ यह नहीं कि हर निवेशक ऐसा ही करता है: जो बरसों तक रखने के लिए ख़रीदते हैं वे भीड़ की अनदेखी कर सकते हैं -- यद्यपि, जैसा कीन्स ने कहा, प्रतीक्षा करते समय वे मूर्ख दिख सकते हैं।

प्रतियोगिता में एक पाठक को स्वयं चेहरा 12 सबसे सुंदर लगता है, पर उसका अनुमान है कि अधिकांश प्रतियोगी चेहरा 40 को लोकप्रिय चुनाव मानेंगे। परिच्छेद के तर्क के अनुसार, जीतने के लिए पाठक को दोनों में से किस चेहरे को प्राथमिकता देनी चाहिए?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p05", "csat_order": 35}'::jsonb,'[{"id": "a", "body": "Face 12, which the reader personally finds the prettiest of all", "body_hi": "चेहरा 12, जो पाठक को स्वयं सबसे सुंदर लगता है", "isCorrect": false}, {"id": "b", "body": "Face 40, which the reader expects the others to expect to be popular", "body_hi": "चेहरा 40, जिसके बारे में पाठक का अनुमान है कि दूसरे उसे लोकप्रिय मानेंगे", "isCorrect": true}, {"id": "c", "body": "A face that neither the reader nor the others are likely to choose", "body_hi": "ऐसा चेहरा जिसे न पाठक चुनेगा न दूसरे चुनेंगे", "isCorrect": false}, {"id": "d", "body": "Neither, since the reader''s own taste and the crowd''s expectation cancel each other out", "body_hi": "कोई नहीं, क्योंकि पाठक की अपनी रुचि और भीड़ की अपेक्षा एक-दूसरे को काट देती हैं", "isCorrect": false}]'::jsonb,2.5,0.83,'The prize goes to whoever comes nearest the average choice, and the passage says a winning reader picks what they expect the others to expect to be popular -- here face 40. Face 12 is the reader''s own taste, which the passage says a winner should set aside; a face that nobody is likely to choose cannot be near the average; and the two views do not cancel out -- the prize rewards matching the crowd''s expectations, not the reader''s taste.','पुरस्कार उसे मिलता है जो औसत चुनाव के सबसे निकट हो, और परिच्छेद कहता है कि जीतने वाला पाठक वह चुनता है जिसके बारे में उसका अनुमान हो कि दूसरे उसे लोकप्रिय मानेंगे -- यहाँ चेहरा 40। चेहरा 12 पाठक की अपनी रुचि है, जिसे परिच्छेद के अनुसार विजेता को अलग रखना चाहिए; जिस चेहरे को किसी के चुनने की संभावना न हो, वह औसत के निकट नहीं हो सकता; और दोनों मत एक-दूसरे को काटते नहीं -- पुरस्कार भीड़ की अपेक्षाओं से मेल खाने का है, पाठक की रुचि का नहीं।','csat-l4-s09-rc-p05-which-face-to-pick','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
In 1936 the economist John Maynard Keynes compared professional investment to a newspaper competition in which readers had to pick the six prettiest faces from a hundred photographs, the prize going to the reader whose choice came nearest to the average choice of all the competitors. To win, a reader should not pick the faces they personally found prettiest, nor even those they thought most people would find prettiest, but those they expected the others to expect to be most popular. In the same way, Keynes argued, investors buying shares for a quick profit try to guess not what a company is truly worth but what other investors will soon think it worth. Prices can then drift far from any sober estimate of value, driven by shifts of mood. The comparison does not mean that every investor behaves so: those who buy to hold for many years can ignore the crowd -- though, as Keynes noted, they may look foolish while they wait.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
1936 में अर्थशास्त्री जॉन मेनार्ड कीन्स ने पेशेवर निवेश की तुलना एक अख़बार की प्रतियोगिता से की, जिसमें पाठकों को सौ तस्वीरों में से छह सबसे सुंदर चेहरे चुनने थे, और पुरस्कार उस पाठक को मिलना था जिसका चुनाव सभी प्रतियोगियों के औसत चुनाव के सबसे निकट हो। जीतने के लिए पाठक को वे चेहरे नहीं चुनने चाहिए जो उसे स्वयं सबसे सुंदर लगें, न वे भी जिन्हें वह सोचता है कि अधिकांश लोग सबसे सुंदर पाएँगे, बल्कि वे जिनके बारे में उसका अनुमान हो कि दूसरे उन्हें सबसे लोकप्रिय मानेंगे। कीन्स का तर्क था कि इसी तरह जल्दी लाभ के लिए शेयर ख़रीदने वाले निवेशक यह अनुमान लगाने का प्रयास करते हैं कि कोई कंपनी वास्तव में कितने की है, यह नहीं, बल्कि यह कि दूसरे निवेशक जल्दी ही उसे कितने का मानेंगे। तब मूल्य किसी भी संयत आकलन से बहुत दूर बह सकते हैं, मनोदशा के बदलावों से प्रेरित होकर। इस तुलना का अर्थ यह नहीं कि हर निवेशक ऐसा ही करता है: जो बरसों तक रखने के लिए ख़रीदते हैं वे भीड़ की अनदेखी कर सकते हैं -- यद्यपि, जैसा कीन्स ने कहा, प्रतीक्षा करते समय वे मूर्ख दिख सकते हैं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["In the competition, a reader''s own taste is of little help in winning the prize.", "Keynes held that share prices always reflect what companies are truly worth."], "statements_hi": ["प्रतियोगिता में पुरस्कार जीतने के लिए पाठक की अपनी रुचि बहुत कम सहायक है।", "कीन्स का मत था कि शेयरों के दाम सदा यह दर्शाते हैं कि कंपनियाँ वास्तव में कितनी मूल्यवान हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p05", "csat_order": 36}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Only 1 is valid. In the contest the prize goes to whoever comes nearest the average choice, so a reader''s own sense of beauty counts for little; the passage says the winner should not pick the faces they personally find prettiest. 2 reverses Keynes: he argued that prices can drift far from any sober estimate of what companies are worth.','केवल 1 वैध है। प्रतियोगिता में पुरस्कार उसे मिलता है जो औसत चुनाव के सबसे निकट हो, इसलिए पाठक की अपनी सौंदर्य-दृष्टि का बहुत कम महत्त्व है; परिच्छेद कहता है कि विजेता को वे चेहरे नहीं चुनने चाहिए जो उसे स्वयं सबसे सुंदर लगें। 2 कीन्स को उलट देता है: उन्होंने तर्क दिया कि मूल्य कंपनियों के वास्तविक मूल्य के किसी भी संयत आकलन से बहुत दूर बह सकते हैं।','csat-l4-s09-rc-p05-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Cube Painting','mcq','medium','A solid block of 27 small cubes, 3 × 3 × 3, is enlarged into a 4 × 4 × 4 block by gluing new small cubes onto three of its faces that meet at one corner. The whole 4 × 4 × 4 block is then painted on the outside. How many of the newly added small cubes have no paint on them?','27 छोटे घनों से बने 3 × 3 × 3 के एक ठोस खंड को, एक कोने पर मिलने वाले उसके तीन फलकों पर नए छोटे घन चिपकाकर, 4 × 4 × 4 का खंड बनाया जाता है। फिर पूरे 4 × 4 × 4 खंड को बाहर से रंगा जाता है। नए जोड़े गए छोटे घनों में से कितनों पर कोई रंग नहीं है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 37}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": true}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "8", "body_hi": "8", "isCorrect": false}, {"id": "d", "body": "37", "body_hi": "37", "isCorrect": false}]'::jsonb,2.5,0.83,'In a 4 × 4 × 4 block only the inner 2 × 2 × 2 core, 8 cubes, escapes the paint. Those 8 sit one layer in from every face, so they all belong to the original 3 × 3 × 3 block. Every new cube lies in the outer layer on one of the three faces where cubes were added, so every one of them is painted: none is bare. 37 is the number of cubes added (64 - 27); 8 is the number of unpainted cubes in the whole block, all of them old; 1 has no basis.','4 × 4 × 4 खंड में केवल भीतर का 2 × 2 × 2 भाग, यानी 8 घन, रंग से बचते हैं। ये 8 हर फलक से एक परत भीतर हैं, इसलिए सभी मूल 3 × 3 × 3 खंड के हैं। हर नया घन उन तीन फलकों में से किसी की बाहरी परत में है जहाँ घन जोड़े गए, इसलिए हर एक पर रंग है: कोई भी बिना रंग का नहीं। 37 जोड़े गए घनों की संख्या है (64 - 27); 8 पूरे खंड के बिना रंग वाले घन हैं, जो सभी पुराने हैं; 1 का कोई आधार नहीं।','csat-l4-s09-lr-cp-a-block-enlarged-and-then-painted','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','statement_based','medium','The shares of a company are held by three people: P holds 45%, Q holds 35% and R holds 20%. Every decision needs the support of holders of more than half of the shares. Which of the following statements is/are correct?','एक कंपनी के शेयर तीन लोगों के पास हैं: P के पास 45%, Q के पास 35% और R के पास 20%। हर निर्णय के लिए आधे से अधिक शेयरों के धारकों का समर्थन चाहिए। निम्नलिखित में से कौन-सा/से कथन सही है/हैं?','{"statements": ["P can pass a decision with the support of either of the others, but R cannot pass one with either.", "Since P holds more than twice as many shares as R, P has more than twice R''s power over decisions."], "statements_hi": ["P दोनों में से किसी के भी समर्थन से निर्णय पारित कर सकता है, पर R किसी के साथ भी नहीं कर सकता।", "चूँकि P के पास R से दोगुने से अधिक शेयर हैं, निर्णयों पर P की शक्ति R से दोगुनी से अधिक है।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 38}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is correct. No one holds more than half alone, but any two together do: P and Q have 80%, P and R 65%, Q and R 55%. 1 fails because R can pass a decision with either P or Q. 2 fails because every holder is equally placed: each can form a majority with either of the other two and none can act alone, so R''s 20% carries as much power over decisions as P''s 45%.','कोई भी सही नहीं। अकेले किसी के पास आधे से अधिक नहीं, पर कोई भी दो मिलकर अधिक रखते हैं: P और Q के 80%, P और R के 65%, Q और R के 55%। 1 विफल है क्योंकि R, P या Q में से किसी के भी साथ निर्णय पारित कर सकता है। 2 विफल है क्योंकि हर धारक की स्थिति बराबर है: हर एक बाक़ी दोनों में से किसी के साथ बहुमत बना सकता है और कोई अकेले कुछ नहीं कर सकता, इसलिए निर्णयों पर R के 20% की शक्ति उतनी ही है जितनी P के 45% की।','csat-l4-s09-qa-rm-shares-that-do-not-measure-power','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','hard','How many different triangles have whole-number sides (in cm) and a perimeter of 12 cm? (Triangles with the same three side lengths count once.)','पूर्ण संख्या वाली भुजाओं (सेमी में) और 12 सेमी परिमाप वाले कितने अलग-अलग त्रिभुज हैं? (एक जैसी तीन भुजाओं वाले त्रिभुज एक बार गिने जाते हैं।)','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 39}'::jsonb,'[{"id": "a", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "b", "body": "3", "body_hi": "3", "isCorrect": true}, {"id": "c", "body": "6", "body_hi": "6", "isCorrect": false}, {"id": "d", "body": "12", "body_hi": "12", "isCorrect": false}]'::jsonb,2.5,0.83,'The longest side must be less than half the perimeter, that is, less than 6 cm, or the other two could not reach round it. With the longest side 5: 2, 5, 5 and 3, 4, 5; with the longest side 4: 4, 4, 4. That makes 3. 6 also counts ''flat'' triangles such as 2, 4, 6, whose sides lie in a straight line; 12 counts every way of splitting 12 into three parts; 1 counts only the equilateral 4, 4, 4.','सबसे लंबी भुजा परिमाप के आधे, यानी 6 सेमी, से कम होनी चाहिए, वरना बाक़ी दो उसके चारों ओर नहीं पहुँच सकतीं। सबसे लंबी भुजा 5 हो तो: 2, 5, 5 और 3, 4, 5; सबसे लंबी 4 हो तो: 4, 4, 4। कुल 3। 6, 2, 4, 6 जैसे ''चपटे'' त्रिभुज भी गिनता है, जिनकी भुजाएँ एक सीधी रेखा में होती हैं; 12, 12 को तीन भागों में बाँटने के हर ढंग को गिनता है; 1 केवल समबाहु 4, 4, 4 गिनता है।','csat-l4-s09-qa-gm-triangles-with-a-perimeter-of-12','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','Every member of the school chess club is in Class 9 or Class 10. No Class 10 student is in the school band. Ravi is in the school band. Which one of the following must be true?','विद्यालय के शतरंज क्लब का हर सदस्य कक्षा 9 या कक्षा 10 में है। कक्षा 10 का कोई विद्यार्थी विद्यालय के बैंड में नहीं है। रवि विद्यालय के बैंड में है। निम्नलिखित में से कौन-सा अवश्य सत्य है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 40}'::jsonb,'[{"id": "a", "body": "Ravi is in Class 9.", "body_hi": "रवि कक्षा 9 में है।", "isCorrect": false}, {"id": "b", "body": "Ravi is not in the chess club.", "body_hi": "रवि शतरंज क्लब में नहीं है।", "isCorrect": false}, {"id": "c", "body": "No member of the chess club is in the school band.", "body_hi": "शतरंज क्लब का कोई सदस्य विद्यालय के बैंड में नहीं है।", "isCorrect": false}, {"id": "d", "body": "If Ravi is in the chess club, Ravi is in Class 9.", "body_hi": "यदि रवि शतरंज क्लब में है, तो रवि कक्षा 9 में है।", "isCorrect": true}]'::jsonb,2.5,0.83,'Ravi is in the band, so Ravi is not in Class 10. If Ravi is also in the chess club, Ravi must be in Class 9 or 10 -- and so in Class 9. That conditional must be true. But nothing says Ravi is in the chess club, so ''Ravi is in Class 9'' need not hold (Ravi could be in another class); nothing rules Ravi out of the club either; and Class 9 members of the club may well play in the band.','रवि बैंड में है, इसलिए रवि कक्षा 10 में नहीं है। यदि रवि शतरंज क्लब में भी है, तो उसे कक्षा 9 या 10 में होना चाहिए -- यानी कक्षा 9 में। यह शर्त वाला कथन अवश्य सत्य है। पर कहीं नहीं कहा गया कि रवि शतरंज क्लब में है, इसलिए ''रवि कक्षा 9 में है'' आवश्यक नहीं (रवि किसी और कक्षा में हो सकता है); कुछ भी रवि को क्लब से बाहर नहीं करता; और क्लब के कक्षा 9 के सदस्य बैंड में हो सकते हैं।','csat-l4-s09-lr-sc-what-a-chess-club-s-rules-make-certain','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
For more than a thousand years, people in the dry regions of western India built stepwells: deep shafts that reach down to the water below the ground, lined with long flights of steps so that people could reach the water however far it had sunk in the dry months. The finest, such as the Rani ki Vav at Patan in Gujarat, built in the eleventh century, are richly carved, with galleries where travellers could rest in the cool. Stepwells were also places where people met, and their upkeep was often a shared duty. Under colonial rule, piped water and hand pumps came to be preferred, many stepwells were judged unhygienic, and many were filled in or left to decay. Some are now being cleaned and revived, as falling groundwater makes their old purpose -- holding water and reaching it through the dry season -- valuable again.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
एक हज़ार से अधिक वर्षों तक पश्चिमी भारत के शुष्क क्षेत्रों में लोगों ने बावड़ियाँ बनाईं: भूमि के नीचे के पानी तक पहुँचने वाले गहरे कुएँ, जिनमें सीढ़ियों की लंबी कतारें होती थीं ताकि सूखे महीनों में पानी कितना भी नीचे चला जाए, लोग उस तक पहुँच सकें। सबसे भव्य बावड़ियाँ, जैसे गुजरात के पाटन की ग्यारहवीं सदी में बनी रानी की वाव, बारीक नक़्क़ाशी वाली हैं, जिनमें ऐसे गलियारे हैं जहाँ यात्री ठंडक में विश्राम कर सकते थे। बावड़ियाँ लोगों के मिलने की जगहें भी थीं, और उनकी देखभाल प्रायः एक साझा कर्तव्य होती थी। औपनिवेशिक शासन में नल के पानी और हैंडपंपों को प्राथमिकता मिली, बहुत-सी बावड़ियों को अस्वच्छ माना गया, और बहुत-सी पाट दी गईं या जर्जर होने को छोड़ दी गईं। कुछ को अब साफ़ करके फिर से जीवित किया जा रहा है, क्योंकि गिरता भूजल उनके पुराने उद्देश्य -- सूखे मौसम भर पानी रखना और उस तक पहुँचना -- को फिर मूल्यवान बना रहा है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p06", "csat_order": 41}'::jsonb,'[{"id": "a", "body": "Neglected stepwells are regaining value as stores of scarce water.", "body_hi": "उपेक्षित बावड़ियाँ दुर्लभ पानी के भंडार के रूप में फिर मूल्यवान हो रही हैं।", "isCorrect": true}, {"id": "b", "body": "Every stepwell in western India is now back in daily use for drinking water.", "body_hi": "पश्चिमी भारत की हर बावड़ी अब पीने के पानी के लिए फिर से रोज़ उपयोग में है।", "isCorrect": false}, {"id": "c", "body": "Stepwells are being revived mainly so that they can attract more tourists.", "body_hi": "बावड़ियों का पुनरुद्धार मुख्यतः इसलिए हो रहा है कि वे और पर्यटक आकर्षित कर सकें।", "isCorrect": false}, {"id": "d", "body": "Piped water should be given up in dry regions in favour of the old stepwells.", "body_hi": "शुष्क क्षेत्रों में पुरानी बावड़ियों के पक्ष में नल का पानी छोड़ देना चाहिए।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage describes stepwells as practical, social and beautiful structures, tells how they fell out of use under colonial rule, and ends with their revival as groundwater falls. It does not say every stepwell is now in use again -- only some are being revived; it gives falling groundwater, not tourism, as the reason; and it presents piped water as what replaced them, not as something to be abandoned.','परिच्छेद बावड़ियों को उपयोगी, सामाजिक और सुंदर संरचनाओं के रूप में वर्णित करता है, बताता है कि औपनिवेशिक शासन में उनका उपयोग कैसे छूटा, और भूजल गिरने पर उनके पुनरुद्धार पर समाप्त होता है। वह यह नहीं कहता कि हर बावड़ी फिर उपयोग में है -- केवल कुछ का पुनरुद्धार हो रहा है; वह कारण गिरता भूजल बताता है, पर्यटन नहीं; और वह नल के पानी को उन्हें बदलने वाली चीज़ बताता है, छोड़ने योग्य चीज़ नहीं।','csat-l4-s09-rc-p06-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','easy','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
For more than a thousand years, people in the dry regions of western India built stepwells: deep shafts that reach down to the water below the ground, lined with long flights of steps so that people could reach the water however far it had sunk in the dry months. The finest, such as the Rani ki Vav at Patan in Gujarat, built in the eleventh century, are richly carved, with galleries where travellers could rest in the cool. Stepwells were also places where people met, and their upkeep was often a shared duty. Under colonial rule, piped water and hand pumps came to be preferred, many stepwells were judged unhygienic, and many were filled in or left to decay. Some are now being cleaned and revived, as falling groundwater makes their old purpose -- holding water and reaching it through the dry season -- valuable again.

According to the passage, why were stepwells built with long flights of steps?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
एक हज़ार से अधिक वर्षों तक पश्चिमी भारत के शुष्क क्षेत्रों में लोगों ने बावड़ियाँ बनाईं: भूमि के नीचे के पानी तक पहुँचने वाले गहरे कुएँ, जिनमें सीढ़ियों की लंबी कतारें होती थीं ताकि सूखे महीनों में पानी कितना भी नीचे चला जाए, लोग उस तक पहुँच सकें। सबसे भव्य बावड़ियाँ, जैसे गुजरात के पाटन की ग्यारहवीं सदी में बनी रानी की वाव, बारीक नक़्क़ाशी वाली हैं, जिनमें ऐसे गलियारे हैं जहाँ यात्री ठंडक में विश्राम कर सकते थे। बावड़ियाँ लोगों के मिलने की जगहें भी थीं, और उनकी देखभाल प्रायः एक साझा कर्तव्य होती थी। औपनिवेशिक शासन में नल के पानी और हैंडपंपों को प्राथमिकता मिली, बहुत-सी बावड़ियों को अस्वच्छ माना गया, और बहुत-सी पाट दी गईं या जर्जर होने को छोड़ दी गईं। कुछ को अब साफ़ करके फिर से जीवित किया जा रहा है, क्योंकि गिरता भूजल उनके पुराने उद्देश्य -- सूखे मौसम भर पानी रखना और उस तक पहुँचना -- को फिर मूल्यवान बना रहा है।

परिच्छेद के अनुसार, बावड़ियाँ सीढ़ियों की लंबी कतारों के साथ क्यों बनाई गईं?','{"craft": "precision", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p06", "csat_order": 42}'::jsonb,'[{"id": "a", "body": "So that the carvings on the walls could be seen from close up", "body_hi": "ताकि दीवारों की नक़्क़ाशी पास से देखी जा सके", "isCorrect": false}, {"id": "b", "body": "So that grain could be stored on the steps above the water", "body_hi": "ताकि पानी के ऊपर की सीढ़ियों पर अनाज रखा जा सके", "isCorrect": false}, {"id": "c", "body": "To reach the water however low it fell in the dry months", "body_hi": "सूखे महीनों में नीचे गए पानी तक पहुँचने के लिए", "isCorrect": true}, {"id": "d", "body": "So that animals could not come down to drink from the water", "body_hi": "ताकि पशु पानी पीने नीचे न आ सकें", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says the steps let people reach the water however far it had sunk in the dry months. It mentions carving and galleries, but not that the steps were for decoration; it says nothing of steps for storing grain or for keeping animals away.','परिच्छेद कहता है कि सीढ़ियों से लोग सूखे महीनों में पानी तक पहुँच सकते थे, वह कितना भी नीचे चला गया हो। वह नक़्क़ाशी और गलियारों का उल्लेख करता है, पर यह नहीं कहता कि सीढ़ियाँ सजावट के लिए थीं; वह अनाज रखने या पशुओं को दूर रखने के लिए सीढ़ियों के बारे में कुछ नहीं कहता।','csat-l4-s09-rc-p06-why-the-steps','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','medium','Exactly one of 1,000 blood samples is contaminated. A test can be run on a pool made by mixing drops from any number of samples, and shows only whether the pool contains the contaminated sample. Results take a day, so all the tests must be run at the same time. What is the least number of tests that can always identify the contaminated sample?','1,000 रक्त नमूनों में से ठीक एक दूषित है। किसी भी संख्या में नमूनों की बूँदें मिलाकर बने एक मिश्रण पर परीक्षण किया जा सकता है, जो केवल यह बताता है कि मिश्रण में दूषित नमूना है या नहीं। परिणाम एक दिन में आते हैं, इसलिए सभी परीक्षण एक साथ करने होंगे। कम से कम कितने परीक्षण सदा दूषित नमूना पहचान सकते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 43}'::jsonb,'[{"id": "a", "body": "10", "body_hi": "10", "isCorrect": true}, {"id": "b", "body": "20", "body_hi": "20", "isCorrect": false}, {"id": "c", "body": "32", "body_hi": "32", "isCorrect": false}, {"id": "d", "body": "500", "body_hi": "500", "isCorrect": false}]'::jsonb,2.5,0.83,'Number the samples 0 to 999 and write each number in binary, which needs 10 digits since 2¹⁰ = 1,024. Test 1 pools every sample whose first binary digit is 1, test 2 those whose second digit is 1, and so on. The ten results, positive or negative, spell out the contaminated sample''s number. Nine tests give only 2⁹ = 512 patterns, too few for 1,000 samples. 20 runs a second test beside each one for the opposite digit, which adds nothing; 32 comes from a grid of rows and columns, which would need even more tests; 500 tests half the samples one by one.','नमूनों को 0 से 999 तक क्रमांक दें और हर संख्या को द्विआधारी (बाइनरी) में लिखें, जिसमें 10 अंक लगते हैं क्योंकि 2¹⁰ = 1,024। परीक्षण 1 में वे सभी नमूने मिलाएँ जिनका पहला बाइनरी अंक 1 है, परीक्षण 2 में जिनका दूसरा अंक 1 है, इत्यादि। दस परिणाम, धनात्मक या ऋणात्मक, दूषित नमूने का क्रमांक बता देते हैं। नौ परीक्षणों से केवल 2⁹ = 512 पैटर्न बनते हैं, जो 1,000 नमूनों के लिए कम हैं। 20 हर परीक्षण के साथ उलटे अंक के लिए दूसरा परीक्षण चलाता है, जिससे कुछ नहीं जुड़ता; 32 पंक्तियों और स्तंभों के ग्रिड से आता है, जिसमें और भी अधिक परीक्षण लगते; 500 आधे नमूनों को एक-एक करके जाँचता है।','csat-l4-s09-qa-ph-samples-tested-in-pools','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','easy','A thali comes with a choice of 6 different side dishes. A diner may take any number of them, but must take at least one. How many different selections are possible?','एक थाली के साथ 6 अलग-अलग सहायक व्यंजनों का विकल्प है। भोजन करने वाला उनमें से कितने भी ले सकता है, पर कम से कम एक लेना आवश्यक है। कितने अलग-अलग चयन संभव हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 44}'::jsonb,'[{"id": "a", "body": "36", "body_hi": "36", "isCorrect": false}, {"id": "b", "body": "63", "body_hi": "63", "isCorrect": true}, {"id": "c", "body": "64", "body_hi": "64", "isCorrect": false}, {"id": "d", "body": "720", "body_hi": "720", "isCorrect": false}]'::jsonb,2.5,0.83,'Each dish is either taken or left: 2 × 2 × 2 × 2 × 2 × 2 = 64 ways, one of which takes nothing. Leaving that out gives 63. 64 forgets to remove the empty selection; 720 = 6! counts orders of serving, not selections; 36 has no basis.','हर व्यंजन या तो लिया जाता है या छोड़ा जाता है: 2 × 2 × 2 × 2 × 2 × 2 = 64 प्रकार, जिनमें एक में कुछ नहीं लिया जाता। उसे छोड़ने पर 63। 64 ख़ाली चयन हटाना भूल जाता है; 720 = 6! परोसने के क्रम गिनता है, चयन नहीं; 36 का कोई आधार नहीं।','csat-l4-s09-qa-pc-side-dishes-on-a-thali','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','After a new expressway halved the travel time between a large city and a small hill town, the number of hotel nights booked in the hill town fell, even though more people visited the town than before. Which one of the following, if true, best explains this?','एक नए एक्सप्रेसवे द्वारा एक बड़े शहर और एक छोटे पहाड़ी कस्बे के बीच यात्रा का समय आधा कर देने के बाद, पहाड़ी कस्बे में होटलों में ठहरने की रातों की संख्या घट गई, यद्यपि पहले से अधिक लोग कस्बे में आए। निम्नलिखित में से कौन-सा, यदि सत्य हो, इसकी सबसे अच्छी व्याख्या करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 45}'::jsonb,'[{"id": "a", "body": "Many visitors who once had to stay overnight can now go back to the city the same day.", "body_hi": "बहुत-से आगंतुक, जिन्हें पहले रात रुकना पड़ता था, अब उसी दिन शहर लौट सकते हैं।", "isCorrect": true}, {"id": "b", "body": "The expressway was built mainly to carry goods traffic rather than tourists to the hills.", "body_hi": "एक्सप्रेसवे मुख्यतः पहाड़ों तक पर्यटकों के बजाय माल ढोने के लिए बनाया गया था।", "isCorrect": false}, {"id": "c", "body": "Hotel rooms in the hill town have always cost less than hotel rooms in the large city.", "body_hi": "पहाड़ी कस्बे के होटल के कमरे सदा बड़े शहर के होटल के कमरों से सस्ते रहे हैं।", "isCorrect": false}, {"id": "d", "body": "The number of people visiting the hill town rose steadily after the expressway opened.", "body_hi": "एक्सप्रेसवे खुलने के बाद पहाड़ी कस्बे में आने वालों की संख्या लगातार बढ़ी।", "isCorrect": false}]'::jsonb,2.5,0.83,'More visitors but fewer hotel nights means each visitor, on average, stays fewer nights. A trip short enough to finish in a day removes the need to stay over -- which reconciles the two facts. Carrying goods says nothing about why visitors stopped staying; cheaper rooms would, if anything, encourage stays; and the rise in visitors is part of the puzzle, not its explanation.','अधिक आगंतुक पर कम होटल-रातें का अर्थ है कि औसतन हर आगंतुक कम रातें रुकता है। एक दिन में पूरी हो जाने लायक़ छोटी यात्रा रुकने की आवश्यकता हटा देती है -- जिससे दोनों तथ्य मेल खा जाते हैं। माल ढोने से यह पता नहीं चलता कि आगंतुकों ने रुकना क्यों छोड़ा; सस्ते कमरे तो रुकने को बढ़ावा देते; और आगंतुकों की बढ़त पहेली का भाग है, उसकी व्याख्या नहीं।','csat-l4-s09-lr-sc-a-faster-road-that-empties-hotels','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: How many students are there in the class?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: कक्षा में कितने विद्यार्थी हैं?','{"statements": ["The students can be split exactly into groups of 6, and also exactly into groups of 8.", "There are more than 40 and fewer than 60 students."], "statements_hi": ["विद्यार्थियों को ठीक 6-6 के समूहों में भी बाँटा जा सकता है, और ठीक 8-8 के समूहों में भी।", "विद्यार्थी 40 से अधिक और 60 से कम हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 46}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: the number is a multiple of both 6 and 8, so a multiple of their LCM, 24 -- 24, 48, 72 and so on. Statement II alone allows any number from 41 to 59. Together, the only multiple of 24 between 40 and 60 is 48. Both statements are needed.','कथन I अकेले: संख्या 6 और 8 दोनों की गुणज है, इसलिए उनके ल.स. 24 की गुणज -- 24, 48, 72 इत्यादि। कथन II अकेले 41 से 59 तक कोई भी संख्या होने देता है। दोनों मिलकर, 40 और 60 के बीच 24 का एकमात्र गुणज 48 है। दोनों कथन आवश्यक हैं।','csat-l4-s09-qa-ds-a-class-split-two-ways-and-bounded','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: A car makes a journey of 120 km. What was its average speed?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: एक कार 120 किमी की यात्रा करती है। उसकी औसत चाल क्या थी?','{"statements": ["The journey took more than 1 hour 30 minutes but less than 2 hours.", "The average speed, in km/h, was a whole number that is a multiple of 5."], "statements_hi": ["यात्रा में 1 घंटा 30 मिनट से अधिक पर 2 घंटे से कम समय लगा।", "औसत चाल, किमी/घंटा में, एक पूर्ण संख्या थी जो 5 की गुणज है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 47}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'Statement I alone puts the speed between 120 ÷ 2 = 60 and 120 ÷ 1.5 = 80 km/h, not including the ends. Statement II alone allows any multiple of 5. Together, the speed could be 65, 70 or 75 km/h -- still more than one value. So even both statements together are not enough.','कथन I अकेले चाल को 120 ÷ 2 = 60 और 120 ÷ 1.5 = 80 किमी/घंटा के बीच रखता है, सिरों को छोड़कर। कथन II अकेले 5 का कोई भी गुणज होने देता है। दोनों मिलकर चाल 65, 70 या 75 किमी/घंटा हो सकती है -- फिर भी एक से अधिक मान। अतः दोनों कथन मिलकर भी पर्याप्त नहीं।','csat-l4-s09-qa-ds-a-speed-boxed-in-but-not-fixed','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: This morning Q was fifth in a queue. What is Q''s position in the queue now?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: आज सुबह Q एक पंक्ति में पाँचवें स्थान पर था। अब पंक्ति में Q का स्थान क्या है?','{"statements": ["Since then, two of the people ahead of Q have left the queue, and nobody has joined it ahead of Q.", "Since then, one of the people behind Q has left the queue."], "statements_hi": ["तब से Q के आगे के दो लोग पंक्ति छोड़ चुके हैं, और Q के आगे कोई नहीं जुड़ा है।", "तब से Q के पीछे के एक व्यक्ति ने पंक्ति छोड़ दी है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 48}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone: Q''s position depends only on how many people are ahead. Four were ahead; two have left and none have joined, so two remain ahead and Q is third. Statement II alone speaks only of people behind Q, which does not change Q''s position, and says nothing about those ahead. One statement alone is enough, but not the other.','कथन I अकेले: Q का स्थान केवल इस पर निर्भर है कि आगे कितने लोग हैं। चार आगे थे; दो चले गए और कोई नहीं जुड़ा, इसलिए दो आगे बचे और Q तीसरा है। कथन II अकेले केवल Q के पीछे के लोगों की बात करता है, जिससे Q का स्थान नहीं बदलता, और आगे वालों के बारे में कुछ नहीं कहता। एक कथन अकेले पर्याप्त है, पर दूसरा नहीं।','csat-l4-s09-lr-ds-a-place-in-a-queue-after-people-leave','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','medium','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Three boxes, P, Q and R, are painted red, green and blue, one colour to each box. What colour is box P?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: तीन डिब्बे, P, Q और R, लाल, हरे और नीले रंग में रंगे हैं, हर डिब्बे का एक रंग। डिब्बा P किस रंग का है?','{"statements": ["P is not red, and Q is red.", "R is blue."], "statements_hi": ["P लाल नहीं है, और Q लाल है।", "R नीला है।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 49}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": true}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": false}]'::jsonb,2.5,0.83,'Statement I alone leaves P green or blue. Statement II alone leaves P red or green. Together, red goes to Q and blue to R, so P is green. Both statements are needed.','कथन I अकेले P को हरा या नीला छोड़ता है। कथन II अकेले P को लाल या हरा छोड़ता है। दोनों मिलकर, लाल Q को और नीला R को जाता है, इसलिए P हरा है। दोनों कथन आवश्यक हैं।','csat-l4-s09-lr-ds-three-boxes-in-three-colours','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Logical Reasoning','Data Sufficiency','mcq','hard','The item below contains a question followed by two statements. Decide whether the data in the statements are sufficient to answer the question.

Question: Are some pens red?','नीचे दिए गए प्रश्नांश में एक प्रश्न और उसके बाद दो कथन हैं। तय कीजिए कि कथनों में दिए गए आँकड़े प्रश्न का उत्तर देने के लिए पर्याप्त हैं या नहीं।

प्रश्न: क्या कुछ पेन लाल हैं?','{"statements": ["All red things are cheap.", "Some pens are cheap."], "statements_hi": ["सभी लाल वस्तुएँ सस्ती हैं।", "कुछ पेन सस्ते हैं।"], "numbering": "roman", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 50}'::jsonb,'[{"id": "a", "body": "The question can be answered using one of the statements alone, but not using the other statement alone", "body_hi": "प्रश्न का उत्तर किसी एक कथन के आधार पर अकेले दिया जा सकता है, पर दूसरे कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "b", "body": "The question can be answered using either statement alone", "body_hi": "प्रश्न का उत्तर किसी भी एक कथन के आधार पर अकेले दिया जा सकता है", "isCorrect": false}, {"id": "c", "body": "The question can be answered using both the statements together, but not using either statement alone", "body_hi": "प्रश्न का उत्तर दोनों कथनों को साथ लेकर दिया जा सकता है, पर किसी भी एक कथन के आधार पर अकेले नहीं", "isCorrect": false}, {"id": "d", "body": "The question cannot be answered even using both the statements together", "body_hi": "दोनों कथनों को साथ लेकर भी प्रश्न का उत्तर नहीं दिया जा सकता", "isCorrect": true}]'::jsonb,2.5,0.83,'Statement I alone says nothing about pens. Statement II alone says nothing about red things. Together they put some pens among cheap things and all red things among cheap things, but the cheap pens and the cheap red things may be quite different things: the pens could all be blue. So even together they do not settle the question.','कथन I अकेले पेनों के बारे में कुछ नहीं कहता। कथन II अकेले लाल वस्तुओं के बारे में कुछ नहीं कहता। दोनों मिलकर कुछ पेनों को सस्ती वस्तुओं में और सभी लाल वस्तुओं को सस्ती वस्तुओं में रखते हैं, पर सस्ते पेन और सस्ती लाल वस्तुएँ बिल्कुल अलग हो सकती हैं: सभी पेन नीले हो सकते हैं। अतः दोनों मिलकर भी प्रश्न तय नहीं करते।','csat-l4-s09-lr-ds-pens-that-may-or-may-not-be-red','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','medium','A, B and C were to share a prize in the ratio 2 : 3 : 4. C drops out, and C''s share is divided between A and B in the ratio of their own shares. What fraction of the prize does A now get?','A, B और C को एक पुरस्कार 2 : 3 : 4 के अनुपात में बाँटना था। C हट जाता है, और C का हिस्सा A और B में उनके अपने हिस्सों के अनुपात में बाँटा जाता है। अब A को पुरस्कार का कितना भाग मिलता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 51}'::jsonb,'[{"id": "a", "body": "1/3", "body_hi": "1/3", "isCorrect": false}, {"id": "b", "body": "2/5", "body_hi": "2/5", "isCorrect": true}, {"id": "c", "body": "4/9", "body_hi": "4/9", "isCorrect": false}, {"id": "d", "body": "1/2", "body_hi": "1/2", "isCorrect": false}]'::jsonb,2.5,0.83,'Passing C''s share on in the ratio 2 : 3 leaves A and B sharing the whole prize in the ratio 2 : 3, so A gets 2/5. (Step by step: A had 2/9 and gets 2/5 of C''s 4/9, which is 8/45; 2/9 + 8/45 = 18/45 = 2/5.) 4/9 splits C''s share equally between A and B; 1/2 splits the whole prize equally; 1/3 keeps three equal shares.','C का हिस्सा 2 : 3 में आगे बाँटने से A और B पूरा पुरस्कार 2 : 3 में बाँटते हैं, इसलिए A को 2/5 मिलता है। (क़दम-दर-क़दम: A के पास 2/9 था और उसे C के 4/9 का 2/5, यानी 8/45, मिलता है; 2/9 + 8/45 = 18/45 = 2/5।) 4/9, C का हिस्सा A और B में बराबर बाँटता है; 1/2 पूरा पुरस्कार बराबर बाँटता है; 1/3 तीन बराबर हिस्से रखता है।','csat-l4-s09-qa-rm-a-share-given-up-and-passed-on','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','How many integers n satisfy n² - 5n + 6 < 0?','कितने पूर्णांक n, n² - 5n + 6 < 0 को संतुष्ट करते हैं?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 52}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": true}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "2", "body_hi": "2", "isCorrect": false}, {"id": "d", "body": "4", "body_hi": "4", "isCorrect": false}]'::jsonb,2.5,0.83,'n² - 5n + 6 = (n - 2)(n - 3), which is negative only when n lies strictly between 2 and 3. No integer does: at n = 2 and n = 3 the expression is 0, not less than 0, and everywhere else it is positive. So there are none. 2 counts the two roots, where the expression equals 0; 1 and 4 have no basis.','n² - 5n + 6 = (n - 2)(n - 3), जो तभी ऋणात्मक होता है जब n ठीक 2 और 3 के बीच हो। कोई पूर्णांक ऐसा नहीं: n = 2 और n = 3 पर व्यंजक 0 है, 0 से कम नहीं, और बाक़ी हर जगह धनात्मक। अतः कोई नहीं। 2 दोनों मूलों को गिनता है, जहाँ व्यंजक 0 के बराबर है; 1 और 4 का कोई आधार नहीं।','csat-l4-s09-qa-nt-no-integer-in-the-gap-between-two-roots','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When India launched Project Tiger in 1973, tigers had been hunted and their forests cleared for decades. The project set aside reserves in which a core area was kept free of human use, with a buffer zone around it. Tiger numbers recovered in many reserves, and national estimates based on camera traps have risen in recent surveys. The approach has had costs, however. Creating some reserves meant moving villages out of the forest, not always with fair compensation; and as tiger numbers grow, more tigers wander out of small, isolated reserves into farmland, where conflict with people follows. Many conservationists now argue that the future lies less in more fencing than in keeping corridors of forest open between reserves, and in giving the people who live beside tigers a stake in their survival.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जब भारत ने 1973 में प्रोजेक्ट टाइगर शुरू किया, तब तक दशकों से बाघों का शिकार हो रहा था और उनके जंगल कट रहे थे। परियोजना ने ऐसे अभयारण्य बनाए जिनमें एक कोर क्षेत्र को मानव उपयोग से मुक्त रखा गया, और उसके चारों ओर एक बफ़र क्षेत्र। बहुत-से अभयारण्यों में बाघों की संख्या फिर बढ़ी, और कैमरा ट्रैप पर आधारित राष्ट्रीय अनुमान हाल के सर्वेक्षणों में बढ़े हैं। पर इस तरीक़े की कुछ लागतें भी रही हैं। कुछ अभयारण्य बनाने के लिए गाँवों को जंगल से बाहर बसाना पड़ा, सदा उचित मुआवज़े के साथ नहीं; और जैसे-जैसे बाघों की संख्या बढ़ती है, अधिक बाघ छोटे, अलग-थलग अभयारण्यों से निकलकर खेतों में आ जाते हैं, जहाँ लोगों से टकराव होता है। बहुत-से संरक्षणवादी अब तर्क देते हैं कि भविष्य और बाड़ लगाने में कम, और अभयारण्यों के बीच जंगल के गलियारे खुले रखने तथा बाघों के पास रहने वाले लोगों को उनके बचे रहने में हिस्सेदार बनाने में अधिक है।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p07", "csat_order": 53}'::jsonb,'[{"id": "a", "body": "Project Tiger has failed, since tiger numbers have kept falling in every reserve.", "body_hi": "प्रोजेक्ट टाइगर विफल रहा है, क्योंकि हर अभयारण्य में बाघों की संख्या घटती रही है।", "isCorrect": false}, {"id": "b", "body": "The best way to protect tigers in future is to fence every reserve more strongly.", "body_hi": "भविष्य में बाघों की रक्षा का सबसे अच्छा ढंग हर अभयारण्य की और मज़बूत बाड़बंदी है।", "isCorrect": false}, {"id": "c", "body": "All villages near tiger reserves should be moved out so that conflict ends.", "body_hi": "बाघ अभयारण्यों के पास के सभी गाँवों को हटा देना चाहिए ताकि टकराव समाप्त हो।", "isCorrect": false}, {"id": "d", "body": "Tigers recovered, but lasting success needs corridors and local goodwill.", "body_hi": "बाघ बढ़े, पर स्थायी सफलता के लिए गलियारे और स्थानीय सहयोग चाहिए।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage credits Project Tiger with a recovery in tiger numbers, sets out its costs to people, and ends with the argument that the next step is corridors and a stake for local people rather than more fencing. It reports a recovery, so it does not say the project failed; it argues against more fencing, not for it; and it says villages were moved, sometimes unfairly -- it does not call for moving all of them.','परिच्छेद बाघों की संख्या में सुधार का श्रेय प्रोजेक्ट टाइगर को देता है, लोगों पर उसकी लागतें बताता है, और इस तर्क पर समाप्त होता है कि अगला क़दम और बाड़ नहीं, बल्कि गलियारे और स्थानीय लोगों की हिस्सेदारी है। वह सुधार की बात करता है, इसलिए यह नहीं कहता कि परियोजना विफल रही; वह और बाड़ के पक्ष में नहीं, उसके विरुद्ध तर्क देता है; और वह कहता है कि गाँव बसाए गए, कभी-कभी अनुचित ढंग से -- वह सबको हटाने की माँग नहीं करता।','csat-l4-s09-rc-p07-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
When India launched Project Tiger in 1973, tigers had been hunted and their forests cleared for decades. The project set aside reserves in which a core area was kept free of human use, with a buffer zone around it. Tiger numbers recovered in many reserves, and national estimates based on camera traps have risen in recent surveys. The approach has had costs, however. Creating some reserves meant moving villages out of the forest, not always with fair compensation; and as tiger numbers grow, more tigers wander out of small, isolated reserves into farmland, where conflict with people follows. Many conservationists now argue that the future lies less in more fencing than in keeping corridors of forest open between reserves, and in giving the people who live beside tigers a stake in their survival.

Which one of the following does the passage present as, in part, a result of the project''s own success?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
जब भारत ने 1973 में प्रोजेक्ट टाइगर शुरू किया, तब तक दशकों से बाघों का शिकार हो रहा था और उनके जंगल कट रहे थे। परियोजना ने ऐसे अभयारण्य बनाए जिनमें एक कोर क्षेत्र को मानव उपयोग से मुक्त रखा गया, और उसके चारों ओर एक बफ़र क्षेत्र। बहुत-से अभयारण्यों में बाघों की संख्या फिर बढ़ी, और कैमरा ट्रैप पर आधारित राष्ट्रीय अनुमान हाल के सर्वेक्षणों में बढ़े हैं। पर इस तरीक़े की कुछ लागतें भी रही हैं। कुछ अभयारण्य बनाने के लिए गाँवों को जंगल से बाहर बसाना पड़ा, सदा उचित मुआवज़े के साथ नहीं; और जैसे-जैसे बाघों की संख्या बढ़ती है, अधिक बाघ छोटे, अलग-थलग अभयारण्यों से निकलकर खेतों में आ जाते हैं, जहाँ लोगों से टकराव होता है। बहुत-से संरक्षणवादी अब तर्क देते हैं कि भविष्य और बाड़ लगाने में कम, और अभयारण्यों के बीच जंगल के गलियारे खुले रखने तथा बाघों के पास रहने वाले लोगों को उनके बचे रहने में हिस्सेदार बनाने में अधिक है।

परिच्छेद निम्नलिखित में से किसे आंशिक रूप से परियोजना की अपनी सफलता का परिणाम बताता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p07", "csat_order": 54}'::jsonb,'[{"id": "a", "body": "More tigers straying from small reserves into farmland", "body_hi": "छोटे अभयारण्यों से अधिक बाघों का खेतों में भटक आना", "isCorrect": true}, {"id": "b", "body": "The hunting of tigers and the clearing of their forests", "body_hi": "बाघों का शिकार और उनके जंगलों का कटना", "isCorrect": false}, {"id": "c", "body": "The moving of villages out of the forest to create reserves", "body_hi": "अभयारण्य बनाने के लिए गाँवों को जंगल से बाहर बसाना", "isCorrect": false}, {"id": "d", "body": "The use of camera traps to estimate the number of tigers", "body_hi": "बाघों की संख्या का अनुमान लगाने के लिए कैमरा ट्रैप का उपयोग", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says that as tiger numbers grow, more tigers wander out of small, isolated reserves into farmland, where conflict follows -- a problem that the recovery itself helps to create. The hunting and forest clearing came before the project; moving villages was a cost of creating reserves, not of rising numbers; and camera-trap surveys are how numbers are counted, not a result of the recovery.','परिच्छेद कहता है कि जैसे-जैसे बाघों की संख्या बढ़ती है, अधिक बाघ छोटे, अलग-थलग अभयारण्यों से निकलकर खेतों में आते हैं, जहाँ टकराव होता है -- एक समस्या जिसे स्वयं सुधार ही पैदा करने में भूमिका निभाता है। शिकार और जंगल कटना परियोजना से पहले के थे; गाँवों को हटाना अभयारण्य बनाने की लागत थी, बढ़ती संख्या की नहीं; और कैमरा ट्रैप सर्वेक्षण संख्या गिनने का ढंग है, सुधार का परिणाम नहीं।','csat-l4-s09-rc-p07-a-problem-that-success-creates','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','medium','Four runners, P, Q, R and S, run the four legs of a relay race, one leg each.
- Q runs the leg immediately after P''s.
- R runs neither the first leg nor the last.
- S runs before R.
Who runs the third leg?','चार धावक, P, Q, R और S, एक रिले दौड़ के चार चरण दौड़ते हैं, हर एक एक चरण।
- Q, P के ठीक बाद वाला चरण दौड़ता है।
- R न पहला चरण दौड़ता है न अंतिम।
- S, R से पहले दौड़ता है।
तीसरा चरण कौन दौड़ता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 55}'::jsonb,'[{"id": "a", "body": "Q", "body_hi": "Q", "isCorrect": false}, {"id": "b", "body": "P", "body_hi": "P", "isCorrect": true}, {"id": "c", "body": "R", "body_hi": "R", "isCorrect": false}, {"id": "d", "body": "S", "body_hi": "S", "isCorrect": false}]'::jsonb,2.5,0.83,'R runs the second or the third leg. If R ran the third, S would run the first or the second, leaving legs 2 and 4 or legs 1 and 4 for P and Q, which are not next to each other -- impossible. So R runs the second leg, S the first (S runs before R), and P and Q take the third and fourth in that order. The order is S, R, P, Q: P runs the third leg. Q runs the fourth, R the second and S the first.','R दूसरा या तीसरा चरण दौड़ता है। यदि R तीसरा दौड़ता, तो S पहला या दूसरा दौड़ता, और P तथा Q के लिए बचे चरण एक-दूसरे के बग़ल में न होते -- असंभव। इसलिए R दूसरा चरण दौड़ता है, S पहला (S, R से पहले दौड़ता है), और P तथा Q उसी क्रम में तीसरा और चौथा लेते हैं। क्रम है S, R, P, Q: तीसरा चरण P दौड़ता है। Q चौथा, R दूसरा और S पहला दौड़ता है।','csat-l4-s09-lr-sa-a-relay-team-s-order-of-legs','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','hard','What is the value of 23³ - 15³ - 8³?','23³ - 15³ - 8³ का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 56}'::jsonb,'[{"id": "a", "body": "7,920", "body_hi": "7,920", "isCorrect": false}, {"id": "b", "body": "8,280", "body_hi": "8,280", "isCorrect": true}, {"id": "c", "body": "8,640", "body_hi": "8,640", "isCorrect": false}, {"id": "d", "body": "9,000", "body_hi": "9,000", "isCorrect": false}]'::jsonb,2.5,0.83,'Write it as a³ + b³ + c³ with a = 23, b = -15 and c = -8. These add up to 0, and whenever a + b + c = 0, a³ + b³ + c³ = 3abc. So the value is 3 × 23 × (-15) × (-8) = 3 × 23 × 120 = 8,280. (Directly: 12,167 - 3,375 - 512 = 8,280.) 7,920 and 8,640 take 3 × 22 × 120 and 3 × 24 × 120, a base off by one; 9,000 has no basis.','इसे a³ + b³ + c³ के रूप में लिखें, जहाँ a = 23, b = -15 और c = -8। इनका योग 0 है, और जब भी a + b + c = 0 हो, a³ + b³ + c³ = 3abc होता है। अतः मान 3 × 23 × (-15) × (-8) = 3 × 23 × 120 = 8,280 है। (सीधे: 12,167 - 3,375 - 512 = 8,280।) 7,920 और 8,640, 3 × 22 × 120 और 3 × 24 × 120 लेते हैं, एक आधार एक से खिसका हुआ; 9,000 का कोई आधार नहीं।','csat-l4-s09-qa-nt-a-cube-sum-whose-bases-add-to-zero','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','easy','A photograph 10 cm wide and 15 cm high is enlarged without changing its shape until it is 24 cm wide. How high is it now?','10 सेमी चौड़ी और 15 सेमी ऊँची एक तस्वीर को उसका आकार-अनुपात बदले बिना 24 सेमी चौड़ा होने तक बड़ा किया जाता है। अब वह कितनी ऊँची है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 57}'::jsonb,'[{"id": "a", "body": "29 cm", "body_hi": "29 सेमी", "isCorrect": false}, {"id": "b", "body": "30 cm", "body_hi": "30 सेमी", "isCorrect": false}, {"id": "c", "body": "36 cm", "body_hi": "36 सेमी", "isCorrect": true}, {"id": "d", "body": "40 cm", "body_hi": "40 सेमी", "isCorrect": false}]'::jsonb,2.5,0.83,'Enlarging without changing the shape multiplies every length by the same factor. The width goes from 10 to 24 cm, a factor of 2.4, so the height becomes 15 × 2.4 = 36 cm (height : width stays 3 : 2). 29 cm adds the 14 cm the width grew by, which would distort the picture; 30 cm doubles the height; 40 cm has no basis.','आकार बदले बिना बड़ा करने से हर लंबाई एक ही गुणक से गुणा होती है। चौड़ाई 10 से 24 सेमी होती है, 2.4 गुना, इसलिए ऊँचाई 15 × 2.4 = 36 सेमी हो जाती है (ऊँचाई : चौड़ाई 3 : 2 ही रहता है)। 29 सेमी उतने ही 14 सेमी जोड़ता है जितनी चौड़ाई बढ़ी, जिससे चित्र विकृत हो जाता; 30 सेमी ऊँचाई दोगुनी करता है; 40 सेमी का कोई आधार नहीं।','csat-l4-s09-qa-rm-a-photograph-enlarged','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','hard','An astrologer made 100 specific predictions last year. A magazine lists the 14 that came true and concludes that the astrologer can foresee events. Which one of the following, if true, most seriously weakens the magazine''s conclusion?','एक ज्योतिषी ने पिछले वर्ष 100 विशिष्ट भविष्यवाणियाँ कीं। एक पत्रिका उनमें से सच निकलीं 14 की सूची देकर निष्कर्ष निकालती है कि ज्योतिषी घटनाओं का पूर्वानुमान कर सकता है। निम्नलिखित में से कौन-सा, यदि सत्य हो, पत्रिका के निष्कर्ष को सबसे गंभीर रूप से कमज़ोर करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 58}'::jsonb,'[{"id": "a", "body": "About as many of the predictions would have come true if they had been mere guesses.", "body_hi": "यदि भविष्यवाणियाँ केवल अनुमान होतीं, तब भी लगभग उतनी ही सच निकलतीं।", "isCorrect": true}, {"id": "b", "body": "The magazine did not say which of the 14 correct predictions was the most important one.", "body_hi": "पत्रिका ने यह नहीं बताया कि 14 सही भविष्यवाणियों में सबसे महत्त्वपूर्ण कौन-सी थी।", "isCorrect": false}, {"id": "c", "body": "Many of the magazine''s readers had heard of the astrologer before the article appeared.", "body_hi": "पत्रिका के बहुत-से पाठकों ने लेख छपने से पहले ही ज्योतिषी के बारे में सुना था।", "isCorrect": false}, {"id": "d", "body": "Some of the 14 predictions that came true were about events in countries far away.", "body_hi": "सच निकलीं 14 भविष्यवाणियों में से कुछ दूर के देशों की घटनाओं के बारे में थीं।", "isCorrect": false}]'::jsonb,2.5,0.83,'The magazine counts the 14 hits and ignores the 86 misses. If guessing would have produced about as many hits, the 14 show no special power at all -- which strikes at the conclusion directly. Which hit mattered most, what readers knew beforehand, and where the events happened say nothing about whether the hits beat chance.','पत्रिका 14 सफलताएँ गिनती है और 86 विफलताओं की अनदेखी करती है। यदि अनुमान से भी लगभग उतनी ही सफलताएँ मिलतीं, तो 14 कोई विशेष शक्ति नहीं दिखातीं -- जो सीधे निष्कर्ष पर चोट करता है। कौन-सी सफलता सबसे महत्त्वपूर्ण थी, पाठक पहले क्या जानते थे, और घटनाएँ कहाँ हुईं -- इनसे यह पता नहीं चलता कि सफलताएँ संयोग से अधिक थीं या नहीं।','csat-l4-s09-lr-sc-an-astrologer-s-hits-counted-without-the-misses','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Geometry & Mensuration','mcq','easy','A plot is a 40 m × 30 m rectangle with a 10 m × 10 m square cut away from one corner. How long a fence is needed to go right round the plot that remains?','एक भूखंड 40 मी × 30 मी का आयत है, जिसके एक कोने से 10 मी × 10 मी का वर्ग काट दिया गया है। बचे हुए भूखंड के चारों ओर पूरी बाड़ के लिए कितनी लंबाई चाहिए?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 59}'::jsonb,'[{"id": "a", "body": "120 m", "body_hi": "120 मी", "isCorrect": false}, {"id": "b", "body": "140 m", "body_hi": "140 मी", "isCorrect": true}, {"id": "c", "body": "160 m", "body_hi": "160 मी", "isCorrect": false}, {"id": "d", "body": "1,100 m", "body_hi": "1,100 मी", "isCorrect": false}]'::jsonb,2.5,0.83,'Cutting the corner removes 10 m from two sides but adds two new edges of 10 m each, so the perimeter is unchanged: 2 × (40 + 30) = 140 m. 120 m subtracts the two lost pieces without adding the new edges; 160 m adds the new edges without subtracting; 1,100 m² is the remaining area, not a length.','कोना काटने से दो भुजाओं से 10 मी घटते हैं पर 10-10 मी के दो नए किनारे जुड़ जाते हैं, इसलिए परिमाप वही रहता है: 2 × (40 + 30) = 140 मी। 120 मी दोनों घटे टुकड़े घटाता है पर नए किनारे नहीं जोड़ता; 160 मी नए किनारे जोड़ता है पर घटाता नहीं; 1,100 वर्ग मी बचा हुआ क्षेत्रफल है, लंबाई नहीं।','csat-l4-s09-qa-gm-a-plot-with-a-corner-cut-away','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
The Right to Information Act, 2005 lets any citizen of India ask a public authority for information it holds, and requires a reply within thirty days, or within forty-eight hours where a person''s life or liberty is at stake. Officials who refuse without good reason can be fined, and appeals go to information commissions. Before the Act, official information was largely secret unless there was a reason to release it; after it, disclosure became the rule and secrecy the exception that has to be justified. Citizens have used the Act to trace ration cards, pensions and the spending of village funds, and to expose wrongdoing at high levels. The Act has limits. Information whose release would harm national security, or would invade privacy without any public interest, can be withheld; many requests go unanswered or are answered late; commissions face long backlogs; and some of those who have used the Act to expose wrongdoing have been threatened or attacked.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सूचना का अधिकार अधिनियम, 2005 भारत के किसी भी नागरिक को किसी लोक प्राधिकरण से उसके पास उपलब्ध सूचना माँगने देता है, और तीस दिनों के भीतर, या जहाँ किसी व्यक्ति के जीवन या स्वतंत्रता का प्रश्न हो वहाँ अड़तालीस घंटों के भीतर, उत्तर देना अनिवार्य करता है। बिना उचित कारण इनकार करने वाले अधिकारियों पर जुर्माना लग सकता है, और अपीलें सूचना आयोगों में जाती हैं। अधिनियम से पहले सरकारी सूचना प्रायः तब तक गोपनीय रहती थी जब तक उसे जारी करने का कोई कारण न हो; उसके बाद प्रकटीकरण नियम बन गया और गोपनीयता ऐसा अपवाद जिसका औचित्य बताना पड़ता है। नागरिकों ने अधिनियम का उपयोग राशन कार्डों, पेंशनों और ग्राम निधियों के ख़र्च का पता लगाने, और ऊँचे स्तरों पर अनियमितताएँ उजागर करने में किया है। अधिनियम की सीमाएँ हैं। जिस सूचना के जारी होने से राष्ट्रीय सुरक्षा को हानि हो, या जो बिना किसी जनहित के निजता में दख़ल दे, उसे रोका जा सकता है; बहुत-से अनुरोधों का उत्तर नहीं आता या देर से आता है; आयोगों में लंबित मामलों का अंबार है; और अनियमितताएँ उजागर करने के लिए अधिनियम का उपयोग करने वाले कुछ लोगों को धमकाया गया है या उन पर हमले हुए हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p08", "csat_order": 60}'::jsonb,'[{"id": "a", "body": "Under the Act every piece of official information must be released to anyone who asks for it.", "body_hi": "अधिनियम के तहत हर सरकारी सूचना माँगने वाले किसी भी व्यक्ति को जारी करनी होगी।", "isCorrect": false}, {"id": "b", "body": "The Act has proved useless, since requests are usually ignored by public officials.", "body_hi": "अधिनियम बेकार सिद्ध हुआ है, क्योंकि सरकारी अधिकारी प्रायः अनुरोधों की अनदेखी करते हैं।", "isCorrect": false}, {"id": "c", "body": "The Act made openness the rule and served citizens, though practice weakens it.", "body_hi": "अधिनियम ने खुलेपन को नियम बनाया और काम आया, यद्यपि व्यवहार में कमज़ोर है।", "isCorrect": true}, {"id": "d", "body": "Requests under the Act are now always answered within thirty days, as the law requires.", "body_hi": "अधिनियम के तहत अनुरोधों का उत्तर अब सदा तीस दिनों के भीतर आता है, जैसा क़ानून कहता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage shows how the Act reversed the default from secrecy to disclosure and has been put to real use, and then sets out its limits in exemptions, delays, backlogs and danger to users. It says some information can be withheld, so not all information must be released; it describes real gains, so it does not call the Act useless; and it says requests are often answered late, not always on time.','परिच्छेद दिखाता है कि अधिनियम ने डिफ़ॉल्ट को गोपनीयता से प्रकटीकरण में कैसे बदला और उसका वास्तविक उपयोग हुआ है, फिर छूटों, देरी, लंबित मामलों और उपयोगकर्ताओं के ख़तरे के रूप में उसकी सीमाएँ बताता है। वह कहता है कि कुछ सूचना रोकी जा सकती है, इसलिए सारी सूचना जारी करना अनिवार्य नहीं; वह वास्तविक उपलब्धियाँ बताता है, इसलिए अधिनियम को बेकार नहीं कहता; और वह कहता है कि अनुरोधों का उत्तर प्रायः देर से आता है, सदा समय पर नहीं।','csat-l4-s09-rc-p08-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Specific Detail','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
The Right to Information Act, 2005 lets any citizen of India ask a public authority for information it holds, and requires a reply within thirty days, or within forty-eight hours where a person''s life or liberty is at stake. Officials who refuse without good reason can be fined, and appeals go to information commissions. Before the Act, official information was largely secret unless there was a reason to release it; after it, disclosure became the rule and secrecy the exception that has to be justified. Citizens have used the Act to trace ration cards, pensions and the spending of village funds, and to expose wrongdoing at high levels. The Act has limits. Information whose release would harm national security, or would invade privacy without any public interest, can be withheld; many requests go unanswered or are answered late; commissions face long backlogs; and some of those who have used the Act to expose wrongdoing have been threatened or attacked.

According to the passage, how soon must a reply be given when a person''s life or liberty is at stake?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सूचना का अधिकार अधिनियम, 2005 भारत के किसी भी नागरिक को किसी लोक प्राधिकरण से उसके पास उपलब्ध सूचना माँगने देता है, और तीस दिनों के भीतर, या जहाँ किसी व्यक्ति के जीवन या स्वतंत्रता का प्रश्न हो वहाँ अड़तालीस घंटों के भीतर, उत्तर देना अनिवार्य करता है। बिना उचित कारण इनकार करने वाले अधिकारियों पर जुर्माना लग सकता है, और अपीलें सूचना आयोगों में जाती हैं। अधिनियम से पहले सरकारी सूचना प्रायः तब तक गोपनीय रहती थी जब तक उसे जारी करने का कोई कारण न हो; उसके बाद प्रकटीकरण नियम बन गया और गोपनीयता ऐसा अपवाद जिसका औचित्य बताना पड़ता है। नागरिकों ने अधिनियम का उपयोग राशन कार्डों, पेंशनों और ग्राम निधियों के ख़र्च का पता लगाने, और ऊँचे स्तरों पर अनियमितताएँ उजागर करने में किया है। अधिनियम की सीमाएँ हैं। जिस सूचना के जारी होने से राष्ट्रीय सुरक्षा को हानि हो, या जो बिना किसी जनहित के निजता में दख़ल दे, उसे रोका जा सकता है; बहुत-से अनुरोधों का उत्तर नहीं आता या देर से आता है; आयोगों में लंबित मामलों का अंबार है; और अनियमितताएँ उजागर करने के लिए अधिनियम का उपयोग करने वाले कुछ लोगों को धमकाया गया है या उन पर हमले हुए हैं।

परिच्छेद के अनुसार, जब किसी व्यक्ति के जीवन या स्वतंत्रता का प्रश्न हो, तो उत्तर कितनी जल्दी देना होता है?','{"craft": "precision", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p08", "csat_order": 61}'::jsonb,'[{"id": "a", "body": "Within 24 hours", "body_hi": "24 घंटों के भीतर", "isCorrect": false}, {"id": "b", "body": "Within 48 hours", "body_hi": "48 घंटों के भीतर", "isCorrect": true}, {"id": "c", "body": "Within 7 days", "body_hi": "7 दिनों के भीतर", "isCorrect": false}, {"id": "d", "body": "Within 30 days", "body_hi": "30 दिनों के भीतर", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage says forty-eight hours where a person''s life or liberty is at stake. Thirty days is the ordinary limit; the passage mentions no seven-day limit and no limit of twenty-four hours.','परिच्छेद कहता है कि जहाँ किसी व्यक्ति के जीवन या स्वतंत्रता का प्रश्न हो, वहाँ अड़तालीस घंटे। तीस दिन सामान्य सीमा है; परिच्छेद सात दिन या चौबीस घंटे की किसी सीमा का उल्लेख नहीं करता।','csat-l4-s09-rc-p08-the-urgent-time-limit','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
The Right to Information Act, 2005 lets any citizen of India ask a public authority for information it holds, and requires a reply within thirty days, or within forty-eight hours where a person''s life or liberty is at stake. Officials who refuse without good reason can be fined, and appeals go to information commissions. Before the Act, official information was largely secret unless there was a reason to release it; after it, disclosure became the rule and secrecy the exception that has to be justified. Citizens have used the Act to trace ration cards, pensions and the spending of village funds, and to expose wrongdoing at high levels. The Act has limits. Information whose release would harm national security, or would invade privacy without any public interest, can be withheld; many requests go unanswered or are answered late; commissions face long backlogs; and some of those who have used the Act to expose wrongdoing have been threatened or attacked.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
सूचना का अधिकार अधिनियम, 2005 भारत के किसी भी नागरिक को किसी लोक प्राधिकरण से उसके पास उपलब्ध सूचना माँगने देता है, और तीस दिनों के भीतर, या जहाँ किसी व्यक्ति के जीवन या स्वतंत्रता का प्रश्न हो वहाँ अड़तालीस घंटों के भीतर, उत्तर देना अनिवार्य करता है। बिना उचित कारण इनकार करने वाले अधिकारियों पर जुर्माना लग सकता है, और अपीलें सूचना आयोगों में जाती हैं। अधिनियम से पहले सरकारी सूचना प्रायः तब तक गोपनीय रहती थी जब तक उसे जारी करने का कोई कारण न हो; उसके बाद प्रकटीकरण नियम बन गया और गोपनीयता ऐसा अपवाद जिसका औचित्य बताना पड़ता है। नागरिकों ने अधिनियम का उपयोग राशन कार्डों, पेंशनों और ग्राम निधियों के ख़र्च का पता लगाने, और ऊँचे स्तरों पर अनियमितताएँ उजागर करने में किया है। अधिनियम की सीमाएँ हैं। जिस सूचना के जारी होने से राष्ट्रीय सुरक्षा को हानि हो, या जो बिना किसी जनहित के निजता में दख़ल दे, उसे रोका जा सकता है; बहुत-से अनुरोधों का उत्तर नहीं आता या देर से आता है; आयोगों में लंबित मामलों का अंबार है; और अनियमितताएँ उजागर करने के लिए अधिनियम का उपयोग करने वाले कुछ लोगों को धमकाया गया है या उन पर हमले हुए हैं।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The Act moved the burden of giving reasons from the person asking for information to the official refusing it.", "The time limits in the Act do not by themselves ensure that every request is answered on time."], "statements_hi": ["अधिनियम ने कारण बताने का भार सूचना माँगने वाले से हटाकर उसे देने से इनकार करने वाले अधिकारी पर डाल दिया।", "अधिनियम की समय-सीमाएँ अपने आप यह सुनिश्चित नहीं करतीं कि हर अनुरोध का उत्तर समय पर आए।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p08", "csat_order": 62}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2.5,0.83,'Both are valid. 1: before the Act information was secret unless there was a reason to release it; after it, secrecy became ''the exception that has to be justified'' -- so the burden of giving reasons moved from the person asking to the official refusing. 2: the passage says many requests go unanswered or are answered late, so the Act''s time limits do not by themselves ensure timely replies.','दोनों वैध हैं। 1: अधिनियम से पहले सूचना तब तक गोपनीय थी जब तक उसे जारी करने का कोई कारण न हो; उसके बाद गोपनीयता ''ऐसा अपवाद जिसका औचित्य बताना पड़ता है'' बन गई -- इसलिए कारण बताने का भार माँगने वाले से हटकर इनकार करने वाले अधिकारी पर आ गया। 2: परिच्छेद कहता है कि बहुत-से अनुरोधों का उत्तर नहीं आता या देर से आता है, इसलिए अधिनियम की समय-सीमाएँ अपने आप समय पर उत्तर सुनिश्चित नहीं करतीं।','csat-l4-s09-rc-p08-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Ratio, Mixtures & Alligation','mcq','hard','A man''s will said that if his wife gave birth to a son, the son should get twice as much as the mother, and if she gave birth to a daughter, the mother should get twice as much as the daughter. She gave birth to twins, a son and a daughter. If both conditions of the will are kept, how much does the daughter get from an estate of ₹14 lakh?','एक व्यक्ति की वसीयत में लिखा था कि यदि उसकी पत्नी पुत्र को जन्म दे, तो पुत्र को माँ से दोगुना मिले, और यदि पुत्री को जन्म दे, तो माँ को पुत्री से दोगुना मिले। उसने जुड़वाँ, एक पुत्र और एक पुत्री, को जन्म दिया। यदि वसीयत की दोनों शर्तें मानी जाएँ, तो ₹14 लाख की संपत्ति में से पुत्री को कितना मिलेगा?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 63}'::jsonb,'[{"id": "a", "body": "₹2 lakh", "body_hi": "₹2 लाख", "isCorrect": true}, {"id": "b", "body": "₹4 lakh", "body_hi": "₹4 लाख", "isCorrect": false}, {"id": "c", "body": "about ₹4.7 lakh", "body_hi": "लगभग ₹4.7 लाख", "isCorrect": false}, {"id": "d", "body": "₹8 lakh", "body_hi": "₹8 लाख", "isCorrect": false}]'::jsonb,2.5,0.83,'Son : mother = 2 : 1 and mother : daughter = 2 : 1. Joining them through the mother gives son : mother : daughter = 4 : 2 : 1, seven parts in all. ₹14 lakh ÷ 7 = ₹2 lakh a part, so the daughter gets ₹2 lakh, the mother ₹4 lakh and the son ₹8 lakh. ₹4 lakh and ₹8 lakh are the mother''s and the son''s shares; about ₹4.7 lakh splits the estate equally three ways, ignoring the will.','पुत्र : माँ = 2 : 1 और माँ : पुत्री = 2 : 1। माँ के माध्यम से जोड़ने पर पुत्र : माँ : पुत्री = 4 : 2 : 1, कुल सात भाग। ₹14 लाख ÷ 7 = ₹2 लाख प्रति भाग, इसलिए पुत्री को ₹2 लाख, माँ को ₹4 लाख और पुत्र को ₹8 लाख मिलते हैं। ₹4 लाख और ₹8 लाख माँ और पुत्र के हिस्से हैं; लगभग ₹4.7 लाख वसीयत की अनदेखी कर संपत्ति को तीन बराबर भागों में बाँटता है।','csat-l4-s09-qa-rm-a-will-that-did-not-foresee-twins','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','''I have bought two phones of this brand, and both stopped working within a month. So every phone this company makes is badly built.'' Which one of the following best describes the flaw in this reasoning?','''मैंने इस ब्रांड के दो फ़ोन ख़रीदे, और दोनों एक महीने के भीतर बंद हो गए। इसलिए यह कंपनी जो भी फ़ोन बनाती है, वह ख़राब बना है।'' निम्नलिखित में से कौन-सा इस तर्क की त्रुटि का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 64}'::jsonb,'[{"id": "a", "body": "It assumes that a phone which works for a month will go on working for years.", "body_hi": "यह मान लेता है कि एक महीना चलने वाला फ़ोन बरसों चलता रहेगा।", "isCorrect": false}, {"id": "b", "body": "It relies on claims made in the advertisements of a rival phone company.", "body_hi": "यह किसी प्रतिद्वंद्वी फ़ोन कंपनी के विज्ञापनों के दावों पर निर्भर करता है।", "isCorrect": false}, {"id": "c", "body": "It draws a conclusion about all the company''s phones from just two of them.", "body_hi": "यह केवल दो फ़ोनों से कंपनी के सभी फ़ोनों के बारे में निष्कर्ष निकालता है।", "isCorrect": true}, {"id": "d", "body": "It treats the price of a phone as if it were a reliable sign of its quality.", "body_hi": "यह फ़ोन के मूल्य को उसकी गुणवत्ता का विश्वसनीय संकेत मान लेता है।", "isCorrect": false}]'::jsonb,2.5,0.83,'Two phones out of the many a company makes are far too few to show that every one is badly built; the speaker may simply have been unlucky. The conclusion outruns the evidence. The argument makes no claim about phones lasting years, cites no advertisements, and says nothing about price.','किसी कंपनी के बनाए अनगिनत फ़ोनों में से दो बहुत कम हैं यह दिखाने के लिए कि हर एक ख़राब बना है; हो सकता है बोलने वाला बस अभागा रहा हो। निष्कर्ष प्रमाण से बहुत आगे निकल जाता है। तर्क फ़ोनों के बरसों चलने के बारे में कोई दावा नहीं करता, किसी विज्ञापन का हवाला नहीं देता, और मूल्य पर कुछ नहीं कहता।','csat-l4-s09-lr-sc-two-phones-that-condemn-a-brand','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','medium','Which one of the following fractions lies between 3/7 and 4/9?','निम्नलिखित में से कौन-सी भिन्न 3/7 और 4/9 के बीच स्थित है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 65}'::jsonb,'[{"id": "a", "body": "5/12", "body_hi": "5/12", "isCorrect": false}, {"id": "b", "body": "8/19", "body_hi": "8/19", "isCorrect": false}, {"id": "c", "body": "7/16", "body_hi": "7/16", "isCorrect": true}, {"id": "d", "body": "5/11", "body_hi": "5/11", "isCorrect": false}]'::jsonb,2.5,0.83,'Adding the numerators and the denominators of two fractions always gives a fraction between them: (3 + 4)/(7 + 9) = 7/16. Check: 3/7 ≈ 0.4286, 7/16 = 0.4375 and 4/9 ≈ 0.4444. 5/12 ≈ 0.4167 and 8/19 ≈ 0.4211 are both below 3/7, and 5/11 ≈ 0.4545 is above 4/9.','दो भिन्नों के अंशों और हरों को अलग-अलग जोड़ने से सदा उनके बीच की भिन्न मिलती है: (3 + 4)/(7 + 9) = 7/16। जाँच: 3/7 ≈ 0.4286, 7/16 = 0.4375 और 4/9 ≈ 0.4444। 5/12 ≈ 0.4167 और 8/19 ≈ 0.4211 दोनों 3/7 से कम हैं, और 5/11 ≈ 0.4545, 4/9 से अधिक है।','csat-l4-s09-qa-nt-a-fraction-between-3-over-7-and-4-over-9','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','hard','In how many ways can 12 be written as the sum of three different positive whole numbers, if the order of the numbers does not matter?','12 को तीन अलग-अलग धनात्मक पूर्ण संख्याओं के योग के रूप में कितने प्रकार से लिखा जा सकता है, यदि संख्याओं का क्रम मायने नहीं रखता?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 66}'::jsonb,'[{"id": "a", "body": "5", "body_hi": "5", "isCorrect": false}, {"id": "b", "body": "7", "body_hi": "7", "isCorrect": true}, {"id": "c", "body": "12", "body_hi": "12", "isCorrect": false}, {"id": "d", "body": "42", "body_hi": "42", "isCorrect": false}]'::jsonb,2.5,0.83,'List them with the smallest first: 1 + 2 + 9, 1 + 3 + 8, 1 + 4 + 7, 1 + 5 + 6; 2 + 3 + 7, 2 + 4 + 6; 3 + 4 + 5. Starting with 4 or more is impossible, since 4 + 5 + 6 = 15. That makes 7. 12 also lets numbers repeat, adding 1 + 1 + 10, 2 + 2 + 8, 2 + 5 + 5, 3 + 3 + 6 and 4 + 4 + 4; 42 counts each of the 7 in all 6 orders; 5 has no basis.','सबसे छोटी संख्या पहले रखकर सूची बनाएँ: 1 + 2 + 9, 1 + 3 + 8, 1 + 4 + 7, 1 + 5 + 6; 2 + 3 + 7, 2 + 4 + 6; 3 + 4 + 5। 4 या अधिक से शुरू करना असंभव है, क्योंकि 4 + 5 + 6 = 15। कुल 7। 12 संख्याओं को दोहराने भी देता है, और 1 + 1 + 10, 2 + 2 + 8, 2 + 5 + 5, 3 + 3 + 6 तथा 4 + 4 + 4 जोड़ लेता है; 42 हर एक को सभी 6 क्रमों में गिनता है; 5 का कोई आधार नहीं।','csat-l4-s09-qa-pc-12-as-three-different-parts','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Coding-Decoding','mcq','hard','In a code, each letter is replaced by a different letter; the same letter is always replaced by the same code letter, and different letters by different code letters. If TIGER is written as QZBNX, which one of the following could be the code for TIGRESS?','एक कूट में हर अक्षर को किसी दूसरे अक्षर से बदला जाता है; एक ही अक्षर को सदा एक ही कूट-अक्षर से, और अलग-अलग अक्षरों को अलग-अलग कूट-अक्षरों से। यदि TIGER को QZBNX लिखा जाता है, तो निम्नलिखित में से कौन-सा TIGRESS का कूट हो सकता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 67}'::jsonb,'[{"id": "a", "body": "QZBXNMK", "body_hi": "QZBXNMK", "isCorrect": false}, {"id": "b", "body": "QZBXNZZ", "body_hi": "QZBXNZZ", "isCorrect": false}, {"id": "c", "body": "QZBNXMM", "body_hi": "QZBNXMM", "isCorrect": false}, {"id": "d", "body": "QZBXNMM", "body_hi": "QZBXNMM", "isCorrect": true}]'::jsonb,2.5,0.83,'From TIGER = QZBNX: T = Q, I = Z, G = B, E = N, R = X. So TIGRESS must begin Q Z B X N, and its two S''s must share one code letter that is not already used for another letter. QZBXNMM does exactly that, with S = M. QZBXNMK gives the two S''s different code letters; QZBXNZZ codes S as Z, which already stands for I; and QZBNXMM codes R as N and E as X, the other way round.','TIGER = QZBNX से: T = Q, I = Z, G = B, E = N, R = X। इसलिए TIGRESS, Q Z B X N से शुरू होना चाहिए, और उसके दोनों S का एक ही कूट-अक्षर होना चाहिए जो पहले से किसी दूसरे अक्षर के लिए प्रयुक्त न हो। QZBXNMM ठीक यही करता है, S = M के साथ। QZBXNMK दोनों S को अलग कूट-अक्षर देता है; QZBXNZZ, S को Z लिखता है, जो पहले से I के लिए है; और QZBNXMM, R को N और E को X लिखता है, यानी उलटा।','csat-l4-s09-lr-cd-a-substitution-code-checked-for-consistency','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
During the Crimean War, Florence Nightingale found that far more British soldiers in the army hospitals were dying of diseases such as typhus, typhoid and dysentery than of their wounds. Back in Britain she worked with the statistician William Farr to analyse the army''s records, and in 1858 presented them in diagrams of her own design: wedge-shaped charts in which the area of each slice showed the deaths in a month from each cause. The charts made plain, even to readers who would never study a table of figures, that most of the deaths could have been prevented, and they helped persuade the government to improve sanitation in military hospitals and barracks. Nightingale was not, however, a lone genius who changed policy with a picture: her charts worked because she also had the data, powerful allies and years of persistence.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
क्रीमिया युद्ध के दौरान फ़्लोरेंस नाइटिंगेल ने पाया कि सेना के अस्पतालों में कहीं अधिक ब्रिटिश सैनिक अपने घावों से नहीं, बल्कि टाइफ़स, टाइफ़ाइड और पेचिश जैसे रोगों से मर रहे थे। ब्रिटेन लौटकर उन्होंने सांख्यिकीविद विलियम फ़ार के साथ सेना के अभिलेखों का विश्लेषण किया, और 1858 में उन्हें अपने बनाए आरेखों में प्रस्तुत किया: फाँक जैसे खंडों वाले चार्ट, जिनमें हर फाँक का क्षेत्रफल हर कारण से एक महीने में हुई मौतें दिखाता था। चार्टों ने उन पाठकों के सामने भी, जो आँकड़ों की तालिका कभी न पढ़ते, यह स्पष्ट कर दिया कि अधिकांश मौतें रोकी जा सकती थीं, और उन्होंने सरकार को सैन्य अस्पतालों और बैरकों में स्वच्छता सुधारने के लिए राज़ी करने में मदद की। पर नाइटिंगेल कोई अकेली प्रतिभा नहीं थीं जिन्होंने एक चित्र से नीति बदल दी: उनके चार्ट इसलिए असरदार रहे कि उनके पास आँकड़े, प्रभावशाली सहयोगी और वर्षों की लगन भी थी।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p09", "csat_order": 68}'::jsonb,'[{"id": "a", "body": "Clear diagrams helped turn evidence into reform, but only with data, allies and persistence.", "body_hi": "स्पष्ट आरेखों ने प्रमाण को सुधार में बदला, पर आँकड़ों, सहयोगियों और लगन के साथ।", "isCorrect": true}, {"id": "b", "body": "Nightingale''s diagrams changed government policy on their own, without any other support.", "body_hi": "नाइटिंगेल के आरेखों ने अपने आप, बिना किसी और सहायता के, सरकार की नीति बदल दी।", "isCorrect": false}, {"id": "c", "body": "Charts are of little use, since officials make decisions only by studying tables of figures.", "body_hi": "चार्ट बहुत कम उपयोगी हैं, क्योंकि अधिकारी केवल आँकड़ों की तालिकाएँ पढ़कर निर्णय लेते हैं।", "isCorrect": false}, {"id": "d", "body": "Most British soldiers in the Crimean War died of their wounds rather than of disease.", "body_hi": "क्रीमिया युद्ध में अधिकांश ब्रिटिश सैनिक रोगों से नहीं, अपने घावों से मरे।", "isCorrect": false}]'::jsonb,2.5,0.83,'The passage shows how Nightingale''s diagrams made the evidence of preventable deaths plain and helped win sanitary reform, while insisting that the charts worked alongside data, allies and persistence. It credits the charts with helping, so it does not call them useless; it explicitly denies that a picture alone changed policy; and it says most deaths were from disease, not wounds.','परिच्छेद दिखाता है कि नाइटिंगेल के आरेखों ने रोकी जा सकने वाली मौतों के प्रमाण को कैसे स्पष्ट किया और स्वच्छता सुधार दिलाने में मदद की, साथ ही इस पर ज़ोर देता है कि चार्ट आँकड़ों, सहयोगियों और लगन के साथ मिलकर असरदार रहे। वह चार्टों को मदद का श्रेय देता है, इसलिए उन्हें बेकार नहीं कहता; वह स्पष्ट नकारता है कि केवल एक चित्र ने नीति बदली; और वह कहता है कि अधिकांश मौतें रोगों से हुईं, घावों से नहीं।','csat-l4-s09-rc-p09-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','statement_based','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
During the Crimean War, Florence Nightingale found that far more British soldiers in the army hospitals were dying of diseases such as typhus, typhoid and dysentery than of their wounds. Back in Britain she worked with the statistician William Farr to analyse the army''s records, and in 1858 presented them in diagrams of her own design: wedge-shaped charts in which the area of each slice showed the deaths in a month from each cause. The charts made plain, even to readers who would never study a table of figures, that most of the deaths could have been prevented, and they helped persuade the government to improve sanitation in military hospitals and barracks. Nightingale was not, however, a lone genius who changed policy with a picture: her charts worked because she also had the data, powerful allies and years of persistence.

On the basis of the passage, which of the following conclusions is/are valid?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
क्रीमिया युद्ध के दौरान फ़्लोरेंस नाइटिंगेल ने पाया कि सेना के अस्पतालों में कहीं अधिक ब्रिटिश सैनिक अपने घावों से नहीं, बल्कि टाइफ़स, टाइफ़ाइड और पेचिश जैसे रोगों से मर रहे थे। ब्रिटेन लौटकर उन्होंने सांख्यिकीविद विलियम फ़ार के साथ सेना के अभिलेखों का विश्लेषण किया, और 1858 में उन्हें अपने बनाए आरेखों में प्रस्तुत किया: फाँक जैसे खंडों वाले चार्ट, जिनमें हर फाँक का क्षेत्रफल हर कारण से एक महीने में हुई मौतें दिखाता था। चार्टों ने उन पाठकों के सामने भी, जो आँकड़ों की तालिका कभी न पढ़ते, यह स्पष्ट कर दिया कि अधिकांश मौतें रोकी जा सकती थीं, और उन्होंने सरकार को सैन्य अस्पतालों और बैरकों में स्वच्छता सुधारने के लिए राज़ी करने में मदद की। पर नाइटिंगेल कोई अकेली प्रतिभा नहीं थीं जिन्होंने एक चित्र से नीति बदल दी: उनके चार्ट इसलिए असरदार रहे कि उनके पास आँकड़े, प्रभावशाली सहयोगी और वर्षों की लगन भी थी।

परिच्छेद के आधार पर निम्नलिखित में से कौन-सा/से निष्कर्ष वैध है/हैं?','{"statements": ["The passage shows that Nightingale''s diagrams were by themselves enough to change government policy.", "In Nightingale''s charts, the length of each slice showed the number of deaths."], "statements_hi": ["परिच्छेद दिखाता है कि नाइटिंगेल के आरेख सरकार की नीति बदलने के लिए अपने आप में पर्याप्त थे।", "नाइटिंगेल के चार्टों में हर फाँक की लंबाई मौतों की संख्या दिखाती थी।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p09", "csat_order": 69}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2.5,0.83,'Neither is valid. 1: the last sentence denies exactly this -- the charts worked because Nightingale also had the data, powerful allies and years of persistence. 2: the passage says the area of each slice showed the deaths, not its length.','कोई भी वैध नहीं। 1: अंतिम वाक्य ठीक इसी को नकारता है -- चार्ट इसलिए असरदार रहे कि नाइटिंगेल के पास आँकड़े, प्रभावशाली सहयोगी और वर्षों की लगन भी थी। 2: परिच्छेद कहता है कि हर फाँक का क्षेत्रफल मौतें दिखाता था, उसकी लंबाई नहीं।','csat-l4-s09-rc-p09-conclusions','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Permutation & Combination','mcq','medium','Four houses stand in a row. Each is to be painted in one of 3 colours so that no two neighbouring houses have the same colour. In how many ways can this be done?','चार मकान एक पंक्ति में हैं। हर एक को 3 में से किसी एक रंग में ऐसे रंगना है कि कोई दो पड़ोसी मकान एक रंग के न हों। यह कितने प्रकार से किया जा सकता है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 70}'::jsonb,'[{"id": "a", "body": "24", "body_hi": "24", "isCorrect": true}, {"id": "b", "body": "27", "body_hi": "27", "isCorrect": false}, {"id": "c", "body": "48", "body_hi": "48", "isCorrect": false}, {"id": "d", "body": "81", "body_hi": "81", "isCorrect": false}]'::jsonb,2.5,0.83,'The first house can take any of the 3 colours. Each house after it can take any colour except its left neighbour''s: 2 choices each. So 3 × 2 × 2 × 2 = 24. 81 = 3⁴ ignores the rule; 27 = 3 × 3 × 3 paints only three houses and ignores the rule for them; 48 doubles the answer for no reason.','पहला मकान 3 में से कोई भी रंग ले सकता है। उसके बाद का हर मकान अपने बाएँ पड़ोसी के रंग को छोड़कर कोई भी रंग ले सकता है: हर बार 2 विकल्प। अतः 3 × 2 × 2 × 2 = 24। 81 = 3⁴ नियम की अनदेखी करता है; 27 = 3 × 3 × 3 केवल तीन मकान रंगता है और उन पर भी नियम छोड़ देता है; 48 उत्तर को बिना कारण दोगुना करता है।','csat-l4-s09-qa-pc-houses-with-no-two-neighbours-alike','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Percentage & Profit-Loss','mcq','medium','If the selling price of an article were doubled, the profit on it would become three times as large. What is the profit percentage at the present selling price?','यदि किसी वस्तु का विक्रय मूल्य दोगुना कर दिया जाए, तो उस पर लाभ तीन गुना हो जाएगा। वर्तमान विक्रय मूल्य पर लाभ प्रतिशत क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 71}'::jsonb,'[{"id": "a", "body": "50%", "body_hi": "50%", "isCorrect": false}, {"id": "b", "body": "100%", "body_hi": "100%", "isCorrect": true}, {"id": "c", "body": "150%", "body_hi": "150%", "isCorrect": false}, {"id": "d", "body": "200%", "body_hi": "200%", "isCorrect": false}]'::jsonb,2.5,0.83,'Let the cost be C and the selling price S. Doubling S gives a profit of 2S - C, which equals 3(S - C). So 2S - C = 3S - 3C, giving S = 2C: the article sells for twice its cost, a profit of 100%. 200% confuses the price being twice the cost with the profit being twice the cost; 50% and 150% have no basis.','मान लें लागत C और विक्रय मूल्य S है। S दोगुना करने पर लाभ 2S - C होता है, जो 3(S - C) के बराबर है। अतः 2S - C = 3S - 3C, जिससे S = 2C: वस्तु अपनी लागत के दोगुने पर बिकती है, यानी 100% लाभ। 200%, मूल्य के लागत का दोगुना होने को लाभ के लागत का दोगुना होने से भ्रमित करता है; 50% और 150% का कोई आधार नहीं।','csat-l4-s09-qa-pp-a-profit-that-triples','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Seating Arrangement','mcq','hard','Four friends -- Anil, Bela, Chirag and Divya -- each keep a different pet (a cat, a dog, a fish or a parrot) and each live in a different city (Agra, Bhopal, Cochin or Delhi).
- The friend who keeps the parrot lives in Cochin.
- Bela keeps the dog.
- Divya lives in Delhi and does not keep the cat.
- The friend who lives in Bhopal keeps the cat.
- Chirag does not live in Bhopal.
Which pet does Divya keep, and where does Bela live?','चार मित्र -- अनिल, बेला, चिराग और दिव्या -- हर एक अलग पालतू (बिल्ली, कुत्ता, मछली या तोता) रखता है और हर एक अलग शहर (आगरा, भोपाल, कोचीन या दिल्ली) में रहता है।
- तोता रखने वाला मित्र कोचीन में रहता है।
- बेला कुत्ता रखती है।
- दिव्या दिल्ली में रहती है और बिल्ली नहीं रखती।
- भोपाल में रहने वाला मित्र बिल्ली रखता है।
- चिराग भोपाल में नहीं रहता।
दिव्या कौन-सा पालतू रखती है, और बेला कहाँ रहती है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 72}'::jsonb,'[{"id": "a", "body": "Parrot; Agra", "body_hi": "तोता; आगरा", "isCorrect": false}, {"id": "b", "body": "Fish; Agra", "body_hi": "मछली; आगरा", "isCorrect": true}, {"id": "c", "body": "Fish; Cochin", "body_hi": "मछली; कोचीन", "isCorrect": false}, {"id": "d", "body": "Cat; Bhopal", "body_hi": "बिल्ली; भोपाल", "isCorrect": false}]'::jsonb,2.5,0.83,'Whoever lives in Bhopal keeps the cat. That cannot be Divya (Delhi), Chirag (not Bhopal) or Bela (who keeps the dog), so Anil lives in Bhopal and keeps the cat. The fish and the parrot are left for Chirag and Divya; the parrot''s keeper lives in Cochin, and Divya lives in Delhi, so Divya keeps the fish and Chirag the parrot, in Cochin. Bela takes the city left over: Agra. ''Parrot'' for Divya ignores that the parrot''s keeper lives in Cochin; Cochin is Chirag''s city, not Bela''s; and the cat and Bhopal belong to Anil.','जो भोपाल में रहता है वह बिल्ली रखता है। वह दिव्या (दिल्ली), चिराग (भोपाल में नहीं) या बेला (जो कुत्ता रखती है) नहीं हो सकता, इसलिए अनिल भोपाल में रहता है और बिल्ली रखता है। मछली और तोता चिराग और दिव्या के लिए बचते हैं; तोते वाला कोचीन में रहता है, और दिव्या दिल्ली में रहती है, इसलिए दिव्या मछली रखती है और चिराग तोता, कोचीन में। बेला बचा हुआ शहर लेती है: आगरा। दिव्या के लिए ''तोता'' इस बात की अनदेखी करता है कि तोते वाला कोचीन में रहता है; कोचीन चिराग का शहर है, बेला का नहीं; और बिल्ली तथा भोपाल अनिल के हैं।','csat-l4-s09-lr-sa-four-friends-with-their-pets-and-cities','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Number Theory','mcq','easy','What is (2 + 4 + 6 + ... + 100) - (1 + 3 + 5 + ... + 99)?','(2 + 4 + 6 + ... + 100) - (1 + 3 + 5 + ... + 99) का मान क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 73}'::jsonb,'[{"id": "a", "body": "0", "body_hi": "0", "isCorrect": false}, {"id": "b", "body": "1", "body_hi": "1", "isCorrect": false}, {"id": "c", "body": "50", "body_hi": "50", "isCorrect": true}, {"id": "d", "body": "100", "body_hi": "100", "isCorrect": false}]'::jsonb,2.5,0.83,'Pair the terms: 2 - 1, 4 - 3, ..., 100 - 99. There are 50 pairs and each is 1, so the difference is 50 -- no need to add up either series. 1 sees only one pair; 100 confuses the number of pairs with the last term; 0 assumes the two sums are equal.','पदों की जोड़ियाँ बनाएँ: 2 - 1, 4 - 3, ..., 100 - 99। 50 जोड़ियाँ हैं और हर एक 1 है, इसलिए अंतर 50 है -- किसी भी श्रेणी को जोड़ने की आवश्यकता नहीं। 1 केवल एक जोड़ी देखता है; 100 जोड़ियों की संख्या को अंतिम पद से भ्रमित करता है; 0 मान लेता है कि दोनों योग बराबर हैं।','csat-l4-s09-qa-nt-the-even-numbers-less-the-odd','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Reading Comprehension','Main Idea','mcq','medium','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Through the twentieth century, average scores on intelligence tests rose steadily in country after country -- by roughly three points a decade, so that the tests had to be made harder every so often to keep the average at 100. The trend is named after the researcher James Flynn, who documented it in the 1980s. The rise was far too fast to be genetic. Better nutrition and health, more and longer schooling, smaller families and a world full of abstract symbols and categories have all been suggested as causes, and they may have worked together. Flynn himself argued that people had not become cleverer in every sense, but more practised at the kinds of abstract thinking the tests reward. In some rich countries the rise has slowed or even reversed since the 1990s, which suggests that whatever drove it has limits.

Which one of the following statements best reflects the crux of the passage?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
बीसवीं सदी भर बुद्धि परीक्षाओं के औसत अंक एक के बाद एक देश में लगातार बढ़े -- मोटे तौर पर प्रति दशक तीन अंक, जिससे औसत को 100 पर रखने के लिए परीक्षाओं को समय-समय पर कठिन करना पड़ा। इस प्रवृत्ति का नाम शोधकर्ता जेम्स फ़्लिन के नाम पर है, जिन्होंने 1980 के दशक में इसे दर्ज किया। यह बढ़त आनुवंशिक होने के लिए बहुत तेज़ थी। बेहतर पोषण और स्वास्थ्य, अधिक और लंबी स्कूली शिक्षा, छोटे परिवार और अमूर्त प्रतीकों तथा श्रेणियों से भरी दुनिया -- सभी को कारण के रूप में सुझाया गया है, और हो सकता है इन्होंने मिलकर काम किया हो। फ़्लिन का अपना तर्क था कि लोग हर अर्थ में अधिक बुद्धिमान नहीं हुए, बल्कि उस प्रकार की अमूर्त सोच में अधिक अभ्यस्त हुए जिसे परीक्षाएँ पुरस्कृत करती हैं। कुछ धनी देशों में 1990 के दशक से यह बढ़त धीमी पड़ी है या उलट भी गई है, जो संकेत देता है कि जो भी इसे चला रहा था उसकी सीमाएँ हैं।

निम्नलिखित में से कौन-सा कथन परिच्छेद के सार को सबसे अच्छी तरह व्यक्त करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p10", "csat_order": 74}'::jsonb,'[{"id": "a", "body": "Test scores rose because the genes of whole populations changed within a few generations.", "body_hi": "परीक्षा-अंक इसलिए बढ़े कि कुछ ही पीढ़ियों के भीतर पूरी की पूरी आबादी के जीन बदल गए।", "isCorrect": false}, {"id": "b", "body": "People in the twentieth century became cleverer in every sense than their grandparents were.", "body_hi": "बीसवीं सदी के लोग अपने दादा-दादी से हर अर्थ में अधिक बुद्धिमान हो गए।", "isCorrect": false}, {"id": "c", "body": "The rise in test scores has continued at the same pace in every country up to the present.", "body_hi": "परीक्षा-अंकों की बढ़त आज तक हर देश में उसी गति से जारी है।", "isCorrect": false}, {"id": "d", "body": "Scores rose for reasons other than genes, reflecting practice more than cleverness.", "body_hi": "अंक आनुवंशिकता के अलावा कारणों से बढ़े, जो बुद्धिमत्ता से अधिक अभ्यास दर्शाते हैं।", "isCorrect": true}]'::jsonb,2.5,0.83,'The passage describes a large rise in test scores, rules out genes, lists possible environmental causes, and adds Flynn''s view that the rise reflects practice at abstract thinking rather than cleverness in every sense -- noting that it has stalled in some places. It says the rise was too fast to be genetic; it does not say people became cleverer in every way -- Flynn denied that; and it says the rise has slowed or reversed in some countries, so it has not continued everywhere.','परिच्छेद परीक्षा-अंकों में बड़ी बढ़त का वर्णन करता है, आनुवंशिकता को अलग करता है, संभावित परिवेशी कारण गिनाता है, और फ़्लिन का मत जोड़ता है कि बढ़त हर अर्थ में बुद्धिमत्ता के बजाय अमूर्त सोच के अभ्यास को दर्शाती है -- यह भी कि कुछ जगहों पर यह रुक गई है। वह कहता है कि बढ़त आनुवंशिक होने के लिए बहुत तेज़ थी; वह यह नहीं कहता कि लोग हर तरह से अधिक बुद्धिमान हुए -- फ़्लिन ने इसे नकारा; और वह कहता है कि कुछ देशों में बढ़त धीमी पड़ी या उलटी, इसलिए वह हर जगह जारी नहीं रही।','csat-l4-s09-rc-p10-crux','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Reading Comprehension','Inference','mcq','hard','Read the following passage and answer the item that follows. Your answer should be based solely on the passage.

Passage
Through the twentieth century, average scores on intelligence tests rose steadily in country after country -- by roughly three points a decade, so that the tests had to be made harder every so often to keep the average at 100. The trend is named after the researcher James Flynn, who documented it in the 1980s. The rise was far too fast to be genetic. Better nutrition and health, more and longer schooling, smaller families and a world full of abstract symbols and categories have all been suggested as causes, and they may have worked together. Flynn himself argued that people had not become cleverer in every sense, but more practised at the kinds of abstract thinking the tests reward. In some rich countries the rise has slowed or even reversed since the 1990s, which suggests that whatever drove it has limits.

Which one of the following findings would best fit Flynn''s own explanation of the rise?','निम्नलिखित परिच्छेद को पढ़िए और उसके बाद दिए गए प्रश्नांश का उत्तर दीजिए। आपका उत्तर केवल परिच्छेद पर आधारित होना चाहिए।

परिच्छेद
बीसवीं सदी भर बुद्धि परीक्षाओं के औसत अंक एक के बाद एक देश में लगातार बढ़े -- मोटे तौर पर प्रति दशक तीन अंक, जिससे औसत को 100 पर रखने के लिए परीक्षाओं को समय-समय पर कठिन करना पड़ा। इस प्रवृत्ति का नाम शोधकर्ता जेम्स फ़्लिन के नाम पर है, जिन्होंने 1980 के दशक में इसे दर्ज किया। यह बढ़त आनुवंशिक होने के लिए बहुत तेज़ थी। बेहतर पोषण और स्वास्थ्य, अधिक और लंबी स्कूली शिक्षा, छोटे परिवार और अमूर्त प्रतीकों तथा श्रेणियों से भरी दुनिया -- सभी को कारण के रूप में सुझाया गया है, और हो सकता है इन्होंने मिलकर काम किया हो। फ़्लिन का अपना तर्क था कि लोग हर अर्थ में अधिक बुद्धिमान नहीं हुए, बल्कि उस प्रकार की अमूर्त सोच में अधिक अभ्यस्त हुए जिसे परीक्षाएँ पुरस्कृत करती हैं। कुछ धनी देशों में 1990 के दशक से यह बढ़त धीमी पड़ी है या उलट भी गई है, जो संकेत देता है कि जो भी इसे चला रहा था उसकी सीमाएँ हैं।

निम्नलिखित में से कौन-सा निष्कर्ष बढ़त की फ़्लिन की अपनी व्याख्या से सबसे अच्छी तरह मेल खाएगा?','{"craft": "inference", "csat_set": "csat-l4-s09", "passage_group": "csat-l4-s09-p10", "csat_order": 75}'::jsonb,'[{"id": "a", "body": "Scores rose by exactly the same amount on every kind of test, in every subject.", "body_hi": "हर प्रकार की परीक्षा में, हर विषय में, अंक ठीक उतने ही बढ़े।", "isCorrect": false}, {"id": "b", "body": "Scores rose most on tests of arithmetic and vocabulary, and least on abstract reasoning.", "body_hi": "अंकगणित और शब्दावली की परीक्षाओं में अंक सबसे अधिक और अमूर्त तर्क में सबसे कम बढ़े।", "isCorrect": false}, {"id": "c", "body": "Scores rose most on abstract-reasoning tests and least on vocabulary and arithmetic.", "body_hi": "अमूर्त तर्क में अंक सबसे अधिक और शब्दावली तथा अंकगणित में सबसे कम बढ़े।", "isCorrect": true}, {"id": "d", "body": "Scores rose only among children whose parents were taller than average.", "body_hi": "अंक केवल उन बच्चों में बढ़े जिनके माता-पिता औसत से लंबे थे।", "isCorrect": false}]'::jsonb,2.5,0.83,'Flynn argued that people had become more practised at the abstract thinking the tests reward, not cleverer in every sense. That predicts the largest gains on tests of abstract reasoning, with little change in skills such as vocabulary and arithmetic. Equal gains everywhere would suggest a general rise in cleverness; gains largest in arithmetic and vocabulary point away from abstract thinking; and a rise only among children of tall parents would suggest a genetic or physical cause, which the passage rules out.','फ़्लिन का तर्क था कि लोग परीक्षाओं द्वारा पुरस्कृत अमूर्त सोच में अधिक अभ्यस्त हुए, हर अर्थ में अधिक बुद्धिमान नहीं। इससे यह अपेक्षा बनती है कि सबसे अधिक बढ़त अमूर्त तर्क की परीक्षाओं में हो, और शब्दावली तथा अंकगणित जैसे कौशलों में बहुत कम बदलाव हो। हर जगह बराबर बढ़त बुद्धिमत्ता में सामान्य वृद्धि का संकेत देती; अंकगणित और शब्दावली में सबसे अधिक बढ़त अमूर्त सोच से दूर ले जाती; और केवल लंबे माता-पिता के बच्चों में बढ़त किसी आनुवंशिक या शारीरिक कारण की ओर संकेत करती, जिसे परिच्छेद नकारता है।','csat-l4-s09-rc-p10-what-fits-flynn-s-view','original_pattern_matched','Original passage and item written for this series in the UPSC CSAT Paper II pattern (2023-26 papers).','draft'),
('upsc','Quantitative Aptitude','Speed-Distance-Time','mcq','medium','The minute hand of a clock is 7 cm long and its hour hand 5 cm long. In a full day, what is the ratio of the distance travelled by the tip of the minute hand to the distance travelled by the tip of the hour hand?','एक घड़ी की मिनट की सुई 7 सेमी लंबी और घंटे की सुई 5 सेमी लंबी है। पूरे दिन में मिनट की सुई की नोक द्वारा तय दूरी और घंटे की सुई की नोक द्वारा तय दूरी का अनुपात क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 76}'::jsonb,'[{"id": "a", "body": "7 : 5", "body_hi": "7 : 5", "isCorrect": false}, {"id": "b", "body": "12 : 1", "body_hi": "12 : 1", "isCorrect": false}, {"id": "c", "body": "84 : 5", "body_hi": "84 : 5", "isCorrect": true}, {"id": "d", "body": "168 : 5", "body_hi": "168 : 5", "isCorrect": false}]'::jsonb,2.5,0.83,'In a day the minute hand goes round 24 times and the hour hand twice. The tips travel 24 × 2π × 7 and 2 × 2π × 5, so the ratio is (24 × 7) : (2 × 5) = 168 : 10 = 84 : 5. 7 : 5 compares only the lengths, as if both hands turned equally often; 12 : 1 compares only the turns, as if the hands were equally long; 168 : 5 has the hour hand going round only once a day.','एक दिन में मिनट की सुई 24 बार घूमती है और घंटे की सुई दो बार। नोकें 24 × 2π × 7 और 2 × 2π × 5 चलती हैं, इसलिए अनुपात (24 × 7) : (2 × 5) = 168 : 10 = 84 : 5 है। 7 : 5 केवल लंबाइयों की तुलना करता है, मानो दोनों सुइयाँ बराबर बार घूमती हों; 12 : 1 केवल चक्करों की, मानो सुइयाँ बराबर लंबी हों; 168 : 5 में घंटे की सुई दिन में केवल एक बार घूमती है।','csat-l4-s09-qa-sdt-the-tips-of-two-clock-hands','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Syllogism','statement_based','easy','Statements: All kettles are appliances. Some appliances are imported.

Which of the following conclusions follow(s) from the statements?','कथन: सभी केतलियाँ उपकरण हैं। कुछ उपकरण आयातित हैं।

निम्नलिखित में से कौन-सा/से निष्कर्ष कथनों से निकलता/निकलते है/हैं?','{"statements": ["Some kettles are imported.", "Some imported things are appliances."], "statements_hi": ["कुछ केतलियाँ आयातित हैं।", "कुछ आयातित वस्तुएँ उपकरण हैं।"], "closing": "Select the correct answer using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए:", "fixed_option_order": true, "craft": "inference", "numbering": "roman", "csat_set": "csat-l4-s09", "csat_order": 77}'::jsonb,'[{"id": "a", "body": "I only", "body_hi": "केवल I", "isCorrect": false}, {"id": "b", "body": "II only", "body_hi": "केवल II", "isCorrect": true}, {"id": "c", "body": "Both I and II", "body_hi": "I और II दोनों", "isCorrect": false}, {"id": "d", "body": "Neither I nor II", "body_hi": "न तो I, न ही II", "isCorrect": false}]'::jsonb,2.5,0.83,'Only II follows: some appliances are imported, which is the same as saying some imported things are appliances. I does not follow: the imported appliances might all be fans or mixers, with not a single kettle among them.','केवल II निकलता है: कुछ उपकरण आयातित हैं, जो यह कहने के समान है कि कुछ आयातित वस्तुएँ उपकरण हैं। I नहीं निकलता: हो सकता है सभी आयातित उपकरण पंखे या मिक्सर हों, और उनमें एक भी केतली न हो।','csat-l4-s09-lr-sy-kettles-and-imported-goods','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft'),
('upsc','Quantitative Aptitude','Puzzle Hybrid','mcq','hard','Two diagonally opposite corner squares are cut from a chessboard, leaving 62 squares. Can the remaining board be covered exactly by 31 dominoes, each domino covering two squares that share a side?','एक शतरंज-बोर्ड से तिरछे आमने-सामने के दो कोने वाले खाने काट दिए जाते हैं, जिससे 62 खाने बचते हैं। क्या बचे बोर्ड को ठीक 31 डोमिनो से ढका जा सकता है, जिनमें हर डोमिनो एक भुजा साझा करने वाले दो खानों को ढकता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 78}'::jsonb,'[{"id": "a", "body": "Yes: the 62 squares that remain are exactly enough for 31 dominoes of two squares each", "body_hi": "हाँ: बचे हुए 62 खाने दो-दो खानों वाले 31 डोमिनो के लिए ठीक पर्याप्त हैं", "isCorrect": false}, {"id": "b", "body": "Yes, but only if some of the dominoes are allowed to lie diagonally across squares", "body_hi": "हाँ, पर केवल तब जब कुछ डोमिनो खानों पर तिरछे रखने की अनुमति हो", "isCorrect": false}, {"id": "c", "body": "No: a board can be covered by dominoes only if its number of squares is a multiple of 4", "body_hi": "नहीं: बोर्ड को डोमिनो से तभी ढका जा सकता है जब उसके खानों की संख्या 4 का गुणज हो", "isCorrect": false}, {"id": "d", "body": "No: the removed squares share a colour, leaving 30 of one colour and 32 of the other", "body_hi": "नहीं: हटाए गए खाने एक ही रंग के हैं, जिससे एक रंग के 30 और दूसरे के 32 बचते हैं", "isCorrect": true}]'::jsonb,2.5,0.83,'Diagonally opposite corners of a chessboard are the same colour, so removing them leaves 30 squares of that colour and 32 of the other. Every domino covers two neighbouring squares, which are always of opposite colours, so 31 dominoes would cover 31 of each colour. The counts do not match, so it cannot be done. Having the right number of squares is not enough, as the colours show; a domino on a diagonal does not cover two squares that share a side; and a multiple of 4 is not required -- a 2 × 3 board of 6 squares is easily covered.','शतरंज-बोर्ड के तिरछे आमने-सामने के कोने एक ही रंग के होते हैं, इसलिए उन्हें हटाने से उस रंग के 30 और दूसरे रंग के 32 खाने बचते हैं। हर डोमिनो दो पड़ोसी खानों को ढकता है, जो सदा विपरीत रंगों के होते हैं, इसलिए 31 डोमिनो हर रंग के 31 खाने ढकते। संख्याएँ मेल नहीं खातीं, इसलिए यह असंभव है। जैसा रंग दिखाते हैं, खानों की सही संख्या पर्याप्त नहीं; तिरछा डोमिनो भुजा साझा करने वाले दो खाने नहीं ढकता; और 4 का गुणज होना आवश्यक नहीं -- 6 खानों वाला 2 × 3 बोर्ड आसानी से ढक जाता है।','csat-l4-s09-qa-ph-a-chessboard-short-of-two-corners','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Quantitative Aptitude','Sequences & Series','mcq','medium','What is the next number in the series 2, 12, 36, 80, 150, ...?','श्रेणी 2, 12, 36, 80, 150, ... की अगली संख्या क्या है?','{"fixed_option_order": true, "craft": "application", "csat_set": "csat-l4-s09", "csat_order": 79}'::jsonb,'[{"id": "a", "body": "210", "body_hi": "210", "isCorrect": false}, {"id": "b", "body": "225", "body_hi": "225", "isCorrect": false}, {"id": "c", "body": "240", "body_hi": "240", "isCorrect": false}, {"id": "d", "body": "252", "body_hi": "252", "isCorrect": true}]'::jsonb,2.5,0.83,'The terms are n² × (n + 1): 1 × 2, 4 × 3, 9 × 4, 16 × 5, 25 × 6. The next is 36 × 7 = 252. (The gaps 10, 24, 44, 70 grow by 14, 20, 26, so the next gap is 70 + 32 = 102, and 150 + 102 = 252.) 240 lets the gaps grow by 20 again (150 + 90); 210 = 5 × 6 × 7 belongs to a different pattern; 225 = 15² has no basis here.','पद n² × (n + 1) हैं: 1 × 2, 4 × 3, 9 × 4, 16 × 5, 25 × 6। अगला 36 × 7 = 252 है। (अंतर 10, 24, 44, 70, 14, 20, 26 से बढ़ते हैं, इसलिए अगला अंतर 70 + 32 = 102 है, और 150 + 102 = 252।) 240 अंतरों को फिर 20 से बढ़ाता है (150 + 90); 210 = 5 × 6 × 7 किसी दूसरे पैटर्न का है; 225 = 15² का यहाँ कोई आधार नहीं।','csat-l4-s09-qa-ss-n-squared-times-n-plus-1','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by direct calculation.','draft'),
('upsc','Logical Reasoning','Statement-Conclusion/Assumption','mcq','medium','A town survey asks residents: ''How much more should the council spend on repairing the dangerous potholes on Station Road?'' Which one of the following best describes the problem with this question?','एक कस्बे का सर्वेक्षण निवासियों से पूछता है: ''स्टेशन रोड के ख़तरनाक गड्ढों की मरम्मत पर परिषद को कितना अधिक ख़र्च करना चाहिए?'' निम्नलिखित में से कौन-सा इस प्रश्न की समस्या का सबसे अच्छा वर्णन करता है?','{"craft": "inference", "csat_set": "csat-l4-s09", "csat_order": 80}'::jsonb,'[{"id": "a", "body": "It asks about only one road, although the town has many other roads that need repairing.", "body_hi": "यह केवल एक सड़क के बारे में पूछता है, यद्यपि कस्बे की कई और सड़कों को मरम्मत चाहिए।", "isCorrect": false}, {"id": "b", "body": "It asks residents about money, a matter on which ordinary people can have no opinion.", "body_hi": "यह निवासियों से पैसे के बारे में पूछता है, ऐसा विषय जिस पर आम लोगों की कोई राय नहीं हो सकती।", "isCorrect": false}, {"id": "c", "body": "It takes for granted that the potholes are dangerous and that more should be spent.", "body_hi": "यह मान लेता है कि गड्ढे ख़तरनाक हैं और उन पर अधिक ख़र्च होना चाहिए।", "isCorrect": true}, {"id": "d", "body": "It uses the word ''council'', which some of the residents who answer may not understand.", "body_hi": "यह ''परिषद'' शब्द का प्रयोग करता है, जिसे उत्तर देने वाले कुछ निवासी शायद न समझें।", "isCorrect": false}]'::jsonb,2.5,0.83,'The question is loaded: whatever figure a resident gives, the answer accepts that the potholes are dangerous and that more money should go to them. Someone who thinks the potholes are minor, or that no more should be spent, has no way to say so. Asking about one road is a choice of topic, not a fault in the wording; residents can hold views on spending; and ''council'' is an ordinary word.','प्रश्न पहले से झुका हुआ है: निवासी जो भी राशि बताए, उत्तर यह स्वीकार कर लेता है कि गड्ढे ख़तरनाक हैं और उन पर अधिक पैसा जाना चाहिए। जो मानता है कि गड्ढे मामूली हैं, या कि और ख़र्च नहीं होना चाहिए, उसके पास यह कहने का कोई रास्ता नहीं। एक सड़क के बारे में पूछना विषय का चुनाव है, शब्दों की त्रुटि नहीं; निवासी ख़र्च पर राय रख सकते हैं; और ''परिषद'' एक सामान्य शब्द है।','csat-l4-s09-lr-sc-a-survey-question-that-assumes-its-answer','original_pattern_matched','Original item in the UPSC CSAT Paper II pattern (2023-26 papers); the key is verified by checking every case.','draft')
